30	/**
31	 * The claims on a sheet: listed per person newest first, added, edited and moved through their
32	 * statuses one at a time. Only a DRAFT can be edited. A voided claim keeps
33	 * its number, which is never reused; a claim opened while period numbering is on is numbered within its
34	 * period instead of sheet-wide. Settling a claim fixes its due at the rate its person's grade has then on the claim's date
35	 * (at least the sheet's floor then), or at the
36	 * figure a statement bound it to, plus the late charge it has then. A claim belongs to the period containing its due-by
37	 * (fixed when it was added, moved past the sheet's holidays then); no claim due by a date inside a closed period can be added, edited or moved,
38	 * and no claim dated after its person's retirement date can be added or edited to that date. A clerk
39	 * settling a claim whose due is above the sheet's clerk limit leaves it PENDING instead; a steward settles
40	 * anything, and approves a PENDING claim (settling it, its due fixed then) or rejects it with a reason
41	 * (back to OPEN), as may the user named as the person's approver; neither the user who opened a claim nor the one who last edited it can settle or approve it. A steward re-settles a SETTLED claim,
42	 * fixing its due again at the figure it would have today as an OPEN claim bound by no statement. A claim
43	 * with a negative amount is a correction: it is added or edited only when it names, by number, a SETTLED
44	 * claim of the same person, and only a correction names one. A claim whose due is above the sheet's proof
45	 * threshold in force on its date cannot be settled or approved while it has no proof. A claim whose due is above
46	 * the sheet's review threshold in force on its date goes to REVIEW when opened, unnumbered, until a steward
47	 * reviews it (OPEN, numbered then).
48	 */
49	@Service
50	public class ClaimService {
51	
52	    private final ClaimRepository claims;
53	    private final PersonRepository people;
54	    private final SheetService sheets;
55	    private final SheetRepository sheetRows;
56	    private final RateService rates;
57	    private final Rollup rollup;
58	    private final PeriodService periods;
59	    private final AccessService access;
60	    private final WatchService watches;
61	    private final HolidayService holidays;
62	    private final Tags tags;
63	    private final VoidReasons voidReasons;
64	    private final ApplicationEventPublisher events;
65	
66	    public ClaimService(ClaimRepository claims, PersonRepository people, SheetService sheets,
67	            SheetRepository sheetRows, RateService rates, Rollup rollup, PeriodService periods, AccessService access,
68	            WatchService watches, HolidayService holidays, Tags tags, VoidReasons voidReasons,
69	            ApplicationEventPublisher events) {
70	        this.tags = tags;
71	        this.voidReasons = voidReasons;
72	        this.holidays = holidays;
73	        this.access = access;
74	        this.watches = watches;
75	        this.rollup = rollup;
76	        this.periods = periods;
77	        this.claims = claims;
78	        this.people = people;
79	        this.sheets = sheets;
80	        this.sheetRows = sheetRows;
81	        this.rates = rates;
82	        this.events = events;
83	    }
84	
85	    /** Every claim on the sheet by the person who made it, each person's newest first. */
86	    @Transactional(readOnly = true)
87	    public Map<Long, List<Claim>> bySheet(String sheetId) {
88	        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
89	                .collect(Collectors.groupingBy(Claim::getPersonId));
90	    }
91	
92	    @Transactional(readOnly = true)
93	    public List<Claim> forPerson(String sheetId, long personId) {
94	        return claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
95	    }
96	
97	    /** Add a claim; a date left out takes the sheet's entry date while set, else its today. Returns the person it belongs to. */
98	    @Transactional
99	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
100	        return add(sheetId, user, personId, amount, date, note, null);
101	    }
102	
103	    /**
104	     * Add a claim, a correction naming the number of the claim it corrects; a date left out takes the
105	     * sheet's entry date while set, else its today. Returns the person it belongs to.
106	     */
107	    @Transactional
108	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
109	            String corrects) {
110	        return add(sheetId, user, personId, amount, date, note, corrects, null);
111	    }
112	
113	    /**
114	     * Add a claim as {@link #add(String, String, long, BigDecimal, LocalDate, String, String)} does, carrying an
115	     * external reference (surrounding spaces removed; blank: none), refused when a claim on the sheet already
116	     * carries it, compared without regard to case. Returns the person it belongs to.
117	     */
118	    @Transactional
119	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
120	            String corrects, String ref) {
121	        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
122	    }
123	
124	    /**
125	     * Add a claim as {@link #add(String, String, long, BigDecimal, LocalDate, String, String, String)} does,
126	     * carrying the tags in the comma separated text (see {@link Tags#normalize}; null: none). Returns the
127	     * person it belongs to.
128	     */
129	    @Transactional
130	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
131	            String corrects, String ref, String tagText) {
132	        return addClaim(sheetId, user, personId, amount, date, note, corrects, ref, tagText).getPersonId();
133	    }
134	
135	    /**
136	     * Add a claim as {@link #add(String, String, long, BigDecimal, LocalDate, String, String, String, String)} does; returns the claim.
137	     * Its due-by is fixed by the terms in force on the day it is created (the sheet's today), not on its date: the
138	     * person's own terms, the terms of the grade they have that day and the sheet's are each looked up on that day.
139	     */
140	    @Transactional
141	    Claim addClaim(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
142	            String corrects, String ref, String tagText) {
143	        String tagged = Tags.normalize(tagText);
144	        String reference = requireFreeRef(sheetId, ref, null);
145	        Person person = people.findByIdAndSheetId(personId, sheetId)
146	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
147	        LocalDate on = date != null ? date : sheets.claimDate(sheetId);
148	        sheets.load(sheetId, user);
149	        LocalDate created = sheets.today(sheetId);
150	        int terms = sheets.settings(sheetId).termsFor(person.termsOn(created), person.gradeOn(created), created);
151	        LocalDate dueBy = holidays.dueBy(sheetId, on, terms);
152	        periods.requireOpen(sheetId, dueBy);
153	        requireNotRetired(person, on);
154	        LocalDate correctsDate = requireCorrects(sheetId, personId, amount, corrects, null);
155	        Rollup.Figures before = rollup.figures(sheetId);
156	        Claim claim = new Claim(sheetId, personId, amount, on, note == null ? "" : note, corrects);
157	        claim.setCorrectsDate(correctsDate);
158	        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy).isPresent());
159	        claim.setDueBy(dueBy);
160	        claim.setTerms(terms);
161	        claim.setRef(reference);
162	        claim.setTags(tagged);
163	        log(sheetId, user, claim, person);
164	        claims.saveAndFlush(claim);
165	        tags.use(sheetId, tagged);
166	        events.publishEvent(new ClaimChanged("CLAIM_ADDED", sheetId, user, person.getName(), amount, on, null, null,
167	                null, null, reference, tagged.isEmpty() ? null : tagged));
168	        if (claim.isLateEntry()) {
169	            events.publishEvent(new ClaimChanged("LATE_ENTRY", sheetId, user, person.getName(), amount, on, null, null));
170	        }
171	        rollup.changed(sheetId, user, before);
172	        return claim;
173	    }
174	
175	    /**
176	     * Edit a claim's amount, date and note; only a DRAFT can be edited (an open claim is voided and
177	     * added again instead), and an edit is refused when a closed period contains its due-by (which an edit
178	     * leaves as it was fixed), or
179	     * when the date it is left with is after its person's retirement date, or when its external reference
180	     * (surrounding spaces removed; blank: none) is carried by another claim on the sheet, compared without
181	     * regard to case, or when the claim has lines and the amount is another than theirs added up. Its tags are
182	     * those in the comma separated text (see {@link Tags#normalize}; null: none).
183	     * Returns the person it belongs to.
184	     */
185	    @Transactional
186	    public long edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
187	            String corrects, String ref, String tagText) {
188	        String tagged = Tags.normalize(tagText);
189	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
190	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
191	        String reference = requireFreeRef(sheetId, ref, claimId);
192	        LocalDate on = date != null ? date : sheets.today(sheetId);
193	        periods.requireOpen(sheetId, claim.getDueBy());
194	        if (claim.getStatus() != ClaimStatus.DRAFT) {
195	            throw new ResponseStatusException(HttpStatus.CONFLICT,
196	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
197	        }
198	        requireNotLockedByOther(claim, user);
199	        if (claim.hasLines() && amount.compareTo(claim.getAmount()) != 0) {
200	            throw new ResponseStatusException(HttpStatus.CONFLICT,
201	                    "The claim's amount is its lines added up (" + claim.getAmount().toPlainString() + ")");
202	        }
203	        people.findByIdAndSheetId(claim.getPersonId(), sheetId).ifPresent(p -> requireNotRetired(p, on));
204	        LocalDate correctsDate = requireCorrects(sheetId, claim.getPersonId(), amount, corrects, claimId);
205	        Rollup.Figures before = rollup.figures(sheetId);
206	        claim.setAmount(amount);
207	        claim.setCorrects(corrects);
208	        claim.setCorrectsDate(correctsDate);
209	        claim.setDate(on);
210	        claim.setNote(note == null ? "" : note);
211	        claim.setRef(reference);
212	        claim.setTags(tagged);
213	        claim.setLockedBy(null);
214	        claim.setEditedBy(user);
215	        claims.flush();
216	        tags.use(sheetId, tagged);
217	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
218	        events.publishEvent(new ClaimChanged("CLAIM_EDITED", sheetId, user, person, claim.getAmount(),
219	                claim.getDate(), claim.getShownNumber(), null));
220	        rollup.changed(sheetId, user, before);
221	        return claim.getPersonId();
222	    }
223	
224	    /**
225	     * Change a claim's amount alone, keeping its date, note and the claim it corrects; refused exactly as
226	     * an {@link #edit} with that amount is. Returns the person it belongs to.
227	     */
228	    @Transactional
229	    public long editAmount(String sheetId, String user, long claimId, BigDecimal amount) {
230	        Claim claim = claim(sheetId, claimId);
231	        return edit(sheetId, user, claimId, amount, claim.getDate(), claim.getNote(), claim.getCorrects(),
232	                claim.getRef(), claim.getTags());
233	    }
234	
235	    /**
236	     * An external reference with its surrounding spaces removed, or null when blank; refused when a claim on
237	     * the sheet other than {@code claimId} (null: any claim) carries it, compared without regard to case.
238	     */
239	    String requireFreeRef(String sheetId, String ref, Long claimId) {
240	        String reference = ref == null || ref.isBlank() ? null : ref.strip();
241	        if (reference != null && (claimId == null ? claims.existsBySheetIdAndRefIgnoreCase(sheetId, reference)
242	                : claims.existsBySheetIdAndRefIgnoreCaseAndIdNot(sheetId, reference, claimId))) {
243	            throw new ResponseStatusException(HttpStatus.CONFLICT,
244	                    "The reference \"" + reference + "\" is already used on the sheet");
245	        }
246	        return reference;
247	    }
248	
249	    /**
250	     * Open a claim's editor, locking the claim for every other user until the editor is saved or cancelled
251	     * or the sheet's today changes. Only a DRAFT due by a date outside every closed period can be edited, and a claim
252	     * another user's editor holds is refused; a refusal takes no lock. No audit line. Returns the person
253	     * it belongs to.
254	     */
255	    @Transactional
256	    public long lock(String sheetId, String user, long claimId) {
257	        Claim claim = claim(sheetId, claimId);
258	        if (claim.getStatus() != ClaimStatus.DRAFT) {
259	            throw new ResponseStatusException(HttpStatus.CONFLICT,
260	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
261	        }
262	        requireNotLockedByOther(claim, user);
263	        claim.setLockedBy(user);
264	        claims.flush();
265	        return claim.getPersonId();
266	    }
267	
268	    /** Cancel a claim's editor, releasing the user's lock on it; another user's lock stays. Returns the person. */
269	    @Transactional
270	    public long unlock(String sheetId, String user, long claimId) {
271	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
272	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
273	        if (user.equals(claim.getLockedBy())) {
274	            claim.setLockedBy(null);
275	            claims.flush();
276	        }
277	        return claim.getPersonId();
278	    }
279	
280	    /** A change of the sheet's today releases every editor's lock on its claims. */
281	    @EventListener
282	    @Transactional
283	    public void on(TodayChanged e) {
284	        claims.findBySheetIdAndLockedByIsNotNull(e.sheetId()).forEach(c -> c.setLockedBy(null));
285	        claims.flush();
286	    }
287	
288	    private static void requireNotLockedByOther(Claim claim, String user) {
289	        if (claim.getLockedBy() != null && !claim.getLockedBy().equals(user)) {
290	            throw new ResponseStatusException(HttpStatus.CONFLICT,
291	                    "The claim is being edited by " + claim.getLockedBy());
292	        }
293	    }
294	
295	    /**
296	     * Move a claim to a status; a move its status does not allow, opening, settling or voiding by a role the
297	     * sheet's permission matrix does not allow, settling by the user who opened
298	     * the claim, or moving a claim due by a date inside a closed period, is refused and changes nothing. Settling
299	     * by a clerk a claim whose due is above the clerk limit leaves it PENDING.
300	     * Returns the person it belongs to.
301	     */
302	    @Transactional
303	    public long move(String sheetId, String user, long claimId, ClaimStatus next) {
304	        return move(sheetId, user, claimId, next, null);
305	    }
306	
307	    /**
308	     * Number a bulk settle that settled the claims (to SETTLED or PENDING) as the sheet's next settle batch,
309	     * each claim showing it, and record it with the frozen figures of those SETTLED added up. Returns the
310	     * batch number.
311	     */
312	    @Transactional
313	    public int settleBatch(String sheetId, String user, List<Long> claimIds) {
314	        int batch = sheets.nextSettleBatch(sheetId);
315	        BigDecimal total = BigDecimal.ZERO;
316	        for (long id : claimIds) {
317	            Claim claim = claim(sheetId, id);
318	            claim.setSettleBatch(batch);
319	            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
320	                total = total.add(claim.getSettledDue());
321	            }
322	        }
323	        claims.flush();
324	        events.publishEvent(new BatchSettled(sheetId, user, batch, claimIds.size(), total));
325	        return batch;
326	    }
327	
328	    /** The number of the sheet's last settle batch; 0 when there has been none. */
329	    public int lastSettleBatch(String sheetId) {
330	        return sheets.lastSettleBatch(sheetId);
331	    }
332	
333	    /**
334	     * Move a claim to a status as {@link #move(String, String, long, ClaimStatus)}; a claim is voided with the
335	     * given reason, which while the sheet's list of void reasons is not empty must be on it, else the void is
336	     * refused (see {@link VoidReasons#require}).
337	     */
338	    @Transactional
339	    public long move(String sheetId, String user, long claimId, ClaimStatus next, String voidReason) {
340	        return move(sheetId, user, claimId, next, voidReason, true);
341	    }
342	
343	    /**
344	     * Move a claim as {@link #move(String, String, long, ClaimStatus, String)}; without the four-eyes and
345	     * proof checks when they were judged on another claim (a part-settle judges them on the claim split).
346	     */
347	    private long move(String sheetId, String user, long claimId, ClaimStatus next, String voidReason,
348	            boolean judgeHere) {
349	        return move(sheetId, user, claimId, next, voidReason, judgeHere, null);
350	    }
351	
352	    /** A claim's due as it stood at the end of a past day of the sheet (null: n/a), to settle it at. */
353	    public record DueThen(LocalDate on, BigDecimal due) {
354	    }
355	
356	    /**
357	     * The claim's due as the sheet shows it now, as of the date given; empty when the sheet has no such
358	     * claim. Read within {@link net.officefloor.hq.app.asof.SheetPasts#asOf}, it is the due as it stood then.
359	     */
360	    java.util.Optional<DueThen> dueThen(String sheetId, long claimId, LocalDate on) {
361	        return claims.findByIdAndSheetId(claimId, sheetId).map(claim -> new DueThen(on,
362	                dueNow(sheetId, claim, people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null))));
363	    }
364	
365	    /**
366	     * Settle a claim as {@link #move(String, String, long, ClaimStatus, String)} does, freezing the due it had
367	     * as of a past day of the sheet in place of today's.
368	     */
369	    @Transactional
370	    public long settleAsOf(String sheetId, String user, long claimId, DueThen then) {
371	        return move(sheetId, user, claimId, ClaimStatus.SETTLED, null, true, then);
372	    }
373	
374	    /** Move a claim; a settle with a due as of a past day freezes that due in place of today's. */
375	    private long move(String sheetId, String user, long claimId, ClaimStatus next, String voidReason,
376	            boolean judgeHere, DueThen then) {
377	        Claim claim = claim(sheetId, claimId);
378	        if (!claim.getStatus().canBecome(next)) {
379	            throw new ResponseStatusException(HttpStatus.CONFLICT,
380	                    "A " + claim.getStatus() + " claim cannot become " + next);
381	        }
382	        Permission permission = switch (next) {
383	            case OPEN -> Permission.OPEN;
384	            case SETTLED -> Permission.SETTLE;
385	            case VOID -> Permission.VOID;
386	            default -> null;
387	        };
388	        if (permission != null && !access.allows(sheetId, user, permission)) {
389	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
390	                    "Your role may not " + permission.action() + " a claim on this sheet");
391	        }
392	        String reasonGiven = next == ClaimStatus.VOID ? voidReasons.require(sheetId, voidReason) : null;
393	        String reversed = null;
394	        if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
395	            requireVoidableSettled(sheetId, user, claim);
396	            reversed = claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString();
397	        }
398	        if (next == ClaimStatus.SETTLED && Dues.deferred(claim, sheets.today(sheetId))) {
399	            throw new ResponseStatusException(HttpStatus.CONFLICT,
400	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then");
401	        }
402	        if (judgeHere && next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
403	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
404	                    "The user who opened a claim cannot settle it");
405	        }
406	        if (judgeHere && next == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
407	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
408	                    "The user who last edited a claim cannot settle it");
409	        }
410	        if (next == ClaimStatus.OPEN) {
411	            requireUnflagged(sheetId, user, claim);
412	            requireNote(sheetId, claim);
413	            requireUnderCap(sheetId, claim);
414	        }
415	        Rollup.Figures before = rollup.figures(sheetId);
416	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
417	        if (next == ClaimStatus.OPEN && needsReview(sheetId, claim, owner)) {
418	            next = ClaimStatus.REVIEW;
419	        }
420	        if (next == ClaimStatus.OPEN) {
421	            giveNumber(sheetId, claim);
422	        }
423	        if (next == ClaimStatus.OPEN || next == ClaimStatus.REVIEW) {
424	            claim.setOpenedBy(user);
425	        }
426	        if (next == ClaimStatus.REVIEW) {
427	            claim.setReviewOn(sheets.today(sheetId));
428	        }
429	        String number = claim.getShownNumber();
430	        String due = null;
431	        if (next == ClaimStatus.SETTLED) {
432	            BigDecimal fixed = then == null ? dueNow(sheetId, claim, owner) : then.due();
433	            if (judgeHere) {
434	                requireProof(sheetId, claim, owner, fixed);
435	            }
436	            String grade = owner == null ? null : owner.gradeOn(sheets.today(sheetId));
437	            if (access.canSettle(sheetId, user, grade, fixed)) {
438	                claim.setSettledDue(fixed);
439	                due = fixed == null ? "n/a" : fixed.toPlainString();
440	            } else {
441	                next = ClaimStatus.PENDING;
442	            }
443	        }
444	        claim.setStatus(next);
445	        if (next == ClaimStatus.VOID) {
446	            claim.setVoidReason(reasonGiven);
447	        }
448	        log(sheetId, user, claim, owner);
449	        claims.flush();
450	        String person = owner == null ? "" : owner.getName();
451	        String event = switch (next) {
452	            case OPEN -> "CLAIM_OPENED";
453	            case REVIEW -> "CLAIM_REVIEW";
454	            case PENDING -> "CLAIM_PENDING";
455	            case SETTLED -> "CLAIM_SETTLED";
456	            case VOID -> "CLAIM_VOIDED";
457	            case DRAFT, DELETED -> throw new IllegalStateException();
458	        };
459	        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number,
460	                due, null, reversed, null, null, reasonGiven,
461	                then != null && next == ClaimStatus.SETTLED ? then.on() : null));
462	        if (next == ClaimStatus.SETTLED) {
463	            watches.notifyWatchers(sheetId, user, owner, number);
464	        }
465	        rollup.changed(sheetId, user, before);
466	        return claim.getPersonId();
467	    }
468	
469	    /** Whether a claim being opened goes to REVIEW: its due (null: n/a) is above the review threshold in force on its date. */
470	    private boolean needsReview(String sheetId, Claim claim, Person owner) {
471	        BigDecimal threshold = sheets.settings(sheetId).reviewThreshold(claim.getDate());
472	        if (threshold == null) {
473	            return false;
474	        }
475	        BigDecimal due = dueNow(sheetId, claim, owner);
476	        return due != null && due.compareTo(threshold) > 0;
477	    }
478	
479	    /**
480	     * A steward reviews a REVIEW claim, opening it: it takes its number then and keeps the user who opened it.
481	     * A claim not REVIEW, one due by a date inside a closed period, or a review by anyone but a steward is
482	     * refused and nothing changes. Returns the person it belongs to.
483	     */
484	    @Transactional
485	    public long review(String sheetId, String user, long claimId) {
486	        Claim claim = claim(sheetId, claimId);
487	        if (claim.getStatus() != ClaimStatus.REVIEW) {
488	            throw new ResponseStatusException(HttpStatus.CONFLICT,
489	                    "A " + claim.getStatus() + " claim cannot be reviewed; only a REVIEW one can");
