633	    /**
634	     * Part-settle an OPEN claim: split the amount off it as {@link #split} does, then settle the new claim
635	     * at once as the user, as settling does (PENDING when the clerk limit says so). The four-eyes rules and
636	     * the proof rule are judged on the claim split, before it is split; a split or a settle that would be
637	     * refused refuses the whole and nothing changes. Returns the person it belongs to.
638	     */
639	    @Transactional
640	    public long settlePart(String sheetId, String user, long claimId, BigDecimal amount) {
641	        Claim claim = claim(sheetId, claimId);
642	        if (user.equals(claim.getOpenedBy())) {
643	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
644	        }
645	        if (user.equals(claim.getEditedBy())) {
646	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
647	                    "The user who last edited a claim cannot settle it");
648	        }
649	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
650	        requireProof(sheetId, claim, owner, dueNow(sheetId, claim, owner));
651	        Claim part = splitOff(sheetId, user, claimId, amount);
652	        return move(sheetId, user, part.getId(), ClaimStatus.SETTLED, null, false);
653	    }
