655	    /** Split an amount off a claim as {@link #split} does, returning the new claim. */
656	    private Claim splitOff(String sheetId, String user, long claimId, BigDecimal amount) {
657	        Claim claim = claim(sheetId, claimId);
658	        if (claim.getStatus() != ClaimStatus.OPEN) {
659	            throw new ResponseStatusException(HttpStatus.CONFLICT,
660	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can");
661	        }
662	        if (Dues.deferred(claim, sheets.today(sheetId))) {
663	            throw new ResponseStatusException(HttpStatus.CONFLICT,
664	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be split");
665	        }
666	        if (!access.allows(sheetId, user, Permission.OPEN)) {
667	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim on this sheet");
668	        }
669	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
670	            throw new ResponseStatusException(HttpStatus.CONFLICT,
671	                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
672	        }
673	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
674	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
675	        Rollup.Figures before = rollup.figures(sheetId);
676	        claim.setAmount(claim.getAmount().subtract(amount));
677	        claim.unbind();
678	        Claim part = new Claim(sheetId, owner.getId(), amount, claim.getDate(), claim.getNote(), null);
679	        sheets.load(sheetId, user);
680	        LocalDate created = sheets.today(sheetId);
681	        int terms = sheets.settings(sheetId).termsFor(owner.termsOn(created), owner.gradeOn(created), created);
682	        part.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
683	        part.setTerms(terms);
684	        part.setSplitFrom(claim.getShownNumber());
685	        part.setTags(claim.getTags());
686	        part.setLateEntry(claim.isLateEntry());
687	        giveNumber(sheetId, part);
688	        part.setOpenedBy(user);
689	        part.setStatus(ClaimStatus.OPEN);
690	        log(sheetId, user, part, owner);
691	        claims.saveAndFlush(part);
692	        events.publishEvent(new ClaimSplit(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
693	                claim.getShownNumber(), part.getShownNumber()));
694	        events.publishEvent(new ClaimChanged("CLAIM_OPENED", sheetId, user, owner.getName(), part.getAmount(),
695	                part.getDate(), part.getShownNumber(), null));
696	        rollup.changed(sheetId, user, before);
697	        return part;
698	    }
