828	    /**
829	     * Remind an OPEN or PENDING claim: it takes the sheet's today as its reminded date. A claim can be
830	     * reminded once per sheet's today; a claim in any other status, or one already reminded on the sheet's
831	     * today, is refused and nothing changes. A reminder changes no figure, so a claim due by a date inside a
832	     * closed period can still be reminded. When the sheet has an escalation gap and the claim's previous
833	     * reminder was at least that many days before the sheet's today, the claim is escalated too (once per
834	     * claim ever). Returns the person it belongs to.
835	     */
836	    @Transactional
837	    public long remind(String sheetId, String user, long claimId) {
838	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
839	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
840	        if (!claim.getStatus().unpaid()) {
841	            throw new ResponseStatusException(HttpStatus.CONFLICT,
842	                    "A " + claim.getStatus() + " claim cannot be reminded; only an OPEN or PENDING one can");
843	        }
844	        LocalDate today = sheets.today(sheetId);
845	        if (today.equals(claim.getRemindedOn())) {
846	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded today (" + today + ")");
847	        }
848	        LocalDate previous = claim.getRemindedOn();
849	        Integer gap = sheets.settings(sheetId).escalateAfter();
850	        boolean escalate = gap != null && previous != null && !claim.isEscalated()
851	                && !previous.plusDays(gap).isAfter(today);
852	        claim.setRemindedOn(today);
853	        if (escalate) {
854	            claim.setEscalated(true);
855	        }
856	        claims.flush();
857	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
858	        events.publishEvent(new ClaimReminded(sheetId, user, person, claim.getAmount(), claim.getDate(),
859	                claim.getShownNumber()));
860	        if (escalate) {
861	            events.publishEvent(new ClaimEscalated(sheetId, user, person, claim.getAmount(), claim.getDate(),
862	                    claim.getShownNumber()));
863	        }
864	        return claim.getPersonId();
865	    }
