872	    private void requireUnflagged(String sheetId, String user, Claim claim) {
873	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
874	        if (owner != null && owner.flagOn(sheets.today(sheetId)) != null
875	                && access.roleOf(sheetId, user) != Role.STEWARD) {
876	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
877	                    "Only a steward can open a claim of " + owner.getName() + ", who is flagged");
