881	    private void requireNote(String sheetId, Claim claim) {
882	        if (claim.getNote() != null && !claim.getNote().isBlank()) {
883	            return;
884	        }
885	        BigDecimal threshold = sheets.settings(sheetId).noteThreshold(claim.getDate());
886	        if (threshold == null) {
887	            return;
888	        }
889	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
890	        BigDecimal due = dueNow(sheetId, claim, owner);
891	        if (due != null && due.compareTo(threshold) > 0) {
892	            throw new ResponseStatusException(HttpStatus.CONFLICT,
893	                    "A claim with a due above " + threshold.toPlainString() + " needs a note to be opened");
894	        }
895	    }
