897	    /**
898	     * Refuse settling or approving a claim with no proof whose due (null: n/a) is above the proof threshold
899	     * in force on the claim's date: its owner's grade's then when one is set, else the sheet's. While the
900	     * sheet's proof kinds are set, such a claim also needs at least one proof of each kind listed.
901	     */
902	    private void requireProof(String sheetId, Claim claim, Person owner, BigDecimal due) {
903	        if (due == null) {
904	            return;
905	        }
906	        String grade = owner == null ? null : owner.gradeOn(claim.getDate());
907	        DatedSettings settings = sheets.settings(sheetId);
908	        BigDecimal threshold = settings.proofThresholdFor(grade, claim.getDate());
909	        if (threshold == null || due.compareTo(threshold) <= 0) {
910	            return;
911	        }
912	        if (claim.getProofs() == 0) {
913	            throw new ResponseStatusException(HttpStatus.CONFLICT,
914	                    "A claim with a due above " + threshold.toPlainString() + " needs a proof to be settled");
915	        }
916	        for (String kind : settings.proofKinds()) {
917	            if (claim.getProofs(kind) == 0) {
918	                throw new ResponseStatusException(HttpStatus.CONFLICT,
919	                        "A claim with a due above " + threshold.toPlainString() + " needs a " + kind + " proof to be settled");
920	            }
921	        }
922	    }
