924	    /**
925	     * Approve a PENDING claim, settling it with its due fixed now (its live figure, late charge frozen in).
926	     * Only a steward or the person's approver approves, never the user who opened the claim or last edited it; a claim not PENDING or due by a date inside a
927	     * closed period is refused and nothing changes. Returns the person it belongs to.
928	     */
929	    @Transactional
930	    public long approve(String sheetId, String user, long claimId) {
931	        Claim claim = pending(sheetId, user, claimId, "approve", "approved");
932	        if (user.equals(claim.getOpenedBy())) {
933	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it");
934	        }
935	        if (user.equals(claim.getEditedBy())) {
936	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
937	                    "The user who last edited a claim cannot approve it");
938	        }
939	        Rollup.Figures before = rollup.figures(sheetId);
940	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
941	        BigDecimal fixed = dueNow(sheetId, claim, owner);
942	        requireProof(sheetId, claim, owner, fixed);
943	        claim.setSettledDue(fixed);
944	        claim.setStatus(ClaimStatus.SETTLED);
945	        log(sheetId, user, claim, owner);
946	        claims.flush();
947	        events.publishEvent(new ClaimChanged("CLAIM_APPROVED", sheetId, user, owner == null ? "" : owner.getName(),
948	                claim.getAmount(), claim.getDate(), claim.getShownNumber(), fixed == null ? "n/a" : fixed.toPlainString()));
949	        watches.notifyWatchers(sheetId, user, owner, claim.getShownNumber());
950	        rollup.changed(sheetId, user, before);
951	        return claim.getPersonId();
952	    }
