954	    /**
955	     * Re-settle a SETTLED claim, fixing its due again at the figure it would have today as an OPEN claim bound
956	     * by no statement (today's rates, grades, floor and late charge), and logging it SETTLED again. Only a
957	     * steward re-settles; a claim not SETTLED or due by a date inside a closed period is refused and nothing changes.
958	     * Returns the person it belongs to.
959	     */
960	    @Transactional
961	    public long resettle(String sheetId, String user, long claimId) {
962	        Claim claim = claim(sheetId, claimId);
963	        if (claim.getStatus() != ClaimStatus.SETTLED) {
964	            throw new ResponseStatusException(HttpStatus.CONFLICT,
965	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
966	        }
967	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
968	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-settle a claim");
969	        }
970	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
971	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
972	        Rollup.Figures before = rollup.figures(sheetId);
973	        BigDecimal old = claim.getSettledDue();
974	        BigDecimal fixed = Dues.asOpen(claim, owner::gradeOn, rates.table(sheetId));
975	        claim.setSettledDue(fixed);
976	        claim.logStatus(user, sheets.today(sheetId), fixed);
977	        claims.flush();
978	        events.publishEvent(new ClaimResettled(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
979	                claim.getShownNumber(), old, fixed));
980	        watches.notifyWatchers(sheetId, user, owner, claim.getShownNumber());
981	        rollup.changed(sheetId, user, before);
982	        return claim.getPersonId();
983	    }
