987	     * that statement counted it). Only a steward or the person's approver rejects; a claim not PENDING or due by a date inside a closed
988	     * period is refused and nothing changes. Returns the person it belongs to.
989	     */
990	    @Transactional
991	    public long reject(String sheetId, String user, long claimId, String reason) {
992	        Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
993	        Rollup.Figures before = rollup.figures(sheetId);
994	        claim.setStatus(ClaimStatus.OPEN);
995	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
996	        log(sheetId, user, claim, owner);
997	        claims.flush();
998	        String person = owner == null ? "" : owner.getName();
999	        events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
1000	                claim.getDate(), claim.getShownNumber(), null, reason));
1001	        rollup.changed(sheetId, user, before);
1002	        return claim.getPersonId();
1003	    }
