1021	     */
1022	    @Transactional
1023	    public long[] reassign(String sheetId, String user, long claimId, long toPersonId, boolean sameAllowed) {
1024	        Claim claim = claim(sheetId, claimId);
1025	        if (!access.allows(sheetId, user, Permission.REASSIGN)) {
1026	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Your role may not reassign a claim on this sheet");
