1189	     * same person, and a claim that is not a correction but names one. Returns the date of the claim a
1190	     * correction corrects (its rounding goes by it); null for any other claim. A correction may not exceed
1191	     * what remains of the claim it corrects: its amount less the corrections already made against it (VOID
1192	     * and DELETED ones left out, and the claim {@code claimId} being edited, null: none).
1193	     */
1194	    private LocalDate requireCorrects(String sheetId, long personId, BigDecimal amount, String corrects,
1195	            Long claimId) {
1196	        if (amount.signum() >= 0) {
1197	            if (corrects != null) {
1198	                throw new ResponseStatusException(HttpStatus.CONFLICT,
1199	                        "Only a correction (a negative amount) names a claim it corrects");
1200	            }
1201	            return null;
1202	        }
1203	        if (corrects == null) {
1204	            throw new ResponseStatusException(HttpStatus.CONFLICT,
1205	                    "A negative amount is a correction; name the number of the settled claim it corrects");
1206	        }
1207	        List<Claim> own = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
1208	        Claim target = own.stream()
1209	                .filter(c -> corrects.equals(c.getShownNumber()) && c.getStatus() == ClaimStatus.SETTLED)
1210	                .findFirst()
1211	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
1212	                        "Claim " + corrects + " is not a settled claim of this person"));
1213	        BigDecimal remaining = own.stream()
1214	                .filter(c -> corrects.equals(c.getCorrects()) && !c.getId().equals(claimId)
1215	                        && c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
1216	                .map(Claim::getAmount).reduce(target.getAmount(), BigDecimal::add);
1217	        if (amount.negate().compareTo(remaining) > 0) {
1218	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A correction of claim " + corrects
1219	                    + " may not exceed what remains of it (" + remaining.max(BigDecimal.ZERO).toPlainString() + ")");
1220	        }
1221	        return target.getDate();
1222	    }
