 24	/**
 25	 * Paste claims: lines of {@code name,amount,date,note} (the note may hold commas and may be left out; a
 26	 * blank date takes the sheet's entry date while set, else its today), each a claim for the person of that name on the sheet,
 27	 * matched as the person form matches names, added and then opened by the user as the open button would, numbered in
 28	 * paste order. A note ending in {@code " #<reference>"} gives the claim that external reference, which is not part of
 29	 * the note. A line whose person, date and note match one of that person's claims as they stood before the paste (void
 30	 * and deleted claims never match) updates that claim instead: the newest matching DRAFT is edited to the line's amount
 31	 * (when it differs) and opened; a line whose matches include no DRAFT is refused. Every line is held to the claim
 32	 * form's and the open button's rules, a reference also to being unused on the sheet and in the paste, and the whole
 33	 * paste is one change: a refused line adds, edits and opens nothing.
 34	 */
 35	@Service
 36	public class PasteClaimsService {
 37	
 38	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,12}(\\.\\d{1,2})?");
 39	    private static final Pattern NOTE_REF = Pattern.compile("(.*) #(\\S.*)");
 40	    private static final int NOTE_MAX = 500;
 41	    private static final int REF_MAX = 100;
 42	
 43	    private record Line(Person person, BigDecimal amount, LocalDate date, String note, String ref) {
 44	    }
 45	
 46	    private final PersonRepository people;
 47	    private final ClaimService claims;
 48	    private final SheetService sheets;
 49	
 50	    public PasteClaimsService(PersonRepository people, ClaimService claims, SheetService sheets) {
 51	        this.people = people;
 52	        this.claims = claims;
 53	        this.sheets = sheets;
 54	    }
 55	
 56	    /** Add or update, then open, a claim per line, in order; returns how many lines went through. */
 57	    @Transactional
 58	    public int paste(String sheetId, String user, String text) {
 59	        List<Line> lines = new ArrayList<>();
 60	        Set<String> refs = new HashSet<>();
 61	        LocalDate claimDate = sheets.claimDate(sheetId);
 62	        Map<Long, List<Claim>> before = new HashMap<>();
 63	        Map<Line, Long> drafts = new IdentityHashMap<>();
 64	        for (String raw : text.split("\\R")) {
 65	            if (raw.isBlank()) continue;
 66	            Line line = parse(sheetId, raw);
 67	            LocalDate on = line.date() != null ? line.date() : claimDate;
 68	            List<Claim> matches = before
 69	                    .computeIfAbsent(line.person().getId(), id -> claims.forPerson(sheetId, id)).stream()
 70	                    .filter(c -> c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
 71	                    .filter(c -> on.equals(c.getDate()) && line.note().equals(c.getNote()))
 72	                    .toList();
 73	            if (!matches.isEmpty()) {
 74	                Claim draft = matches.stream().filter(c -> c.getStatus() == ClaimStatus.DRAFT).findFirst()
 75	                        .orElseThrow(() -> refused(raw, "it matches a claim of " + line.person().getName()
 76	                                + " that is no longer a DRAFT"));
 77	                drafts.put(line, draft.getId());
 78	            }
 79	            if (line.ref() != null) {
 80	                try {
 81	                    claims.requireFreeRef(sheetId, line.ref(), null);
 82	                } catch (ResponseStatusException e) {
 83	                    throw refused(raw, "the reference \"" + line.ref() + "\" is already used on the sheet");
 84	                }
 85	                if (!refs.add(line.ref().toLowerCase(Locale.ROOT))) {
 86	                    throw refused(raw, "the reference \"" + line.ref() + "\" is given twice in the paste");
 87	                }
 88	            }
 89	            lines.add(line);
 90	        }
 91	        if (lines.isEmpty()) {
 92	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Paste at least one line");
 93	        }
 94	        for (Line line : lines) {
 95	            Long id = drafts.get(line);
 96	            if (id == null) {
 97	                id = claims.addClaim(sheetId, user, line.person().getId(), line.amount(), line.date(), line.note(),
 98	                        null, line.ref(), null).getId();
 99	            } else if (claims.claim(sheetId, id).getAmount().compareTo(line.amount()) != 0) {
100	                claims.editAmount(sheetId, user, id, line.amount());
101	            }
102	            claims.move(sheetId, user, id, ClaimStatus.OPEN);
103	        }
104	        return lines.size();
105	    }
106	
107	    private Line parse(String sheetId, String raw) {
108	        String[] f = raw.split(",", 4);
109	        if (f.length < 2) throw refused(raw, "give a name and an amount");
110	        String name = f[0].trim();
111	        Person person = name.isEmpty() ? null
112	                : people.findBySheetIdAndNameOrAlias(sheetId, name).stream().findFirst().orElse(null);
113	        if (person == null) throw refused(raw, "no one named \"" + name + "\" is on the sheet");
114	        String amount = f[1].trim();
115	        if (!AMOUNT.matcher(amount).matches()) throw refused(raw, "the amount must have up to two decimals");
116	        LocalDate date = null;
117	        if (f.length > 2 && !f[2].isBlank()) {
118	            try {
119	                date = LocalDate.parse(f[2].trim());
120	            } catch (DateTimeParseException e) {
121	                throw refused(raw, "the date must be YYYY-MM-DD");
122	            }
123	        }
124	        String note = f.length > 3 ? f[3].trim() : "";
125	        String ref = null;
126	        Matcher tail = NOTE_REF.matcher(note);
127	        if (tail.matches()) {
128	            note = tail.group(1).trim();
129	            ref = tail.group(2).strip();
130	        }
131	        if (note.length() > NOTE_MAX) throw refused(raw, "the note is too long");
132	        if (ref != null && ref.length() > REF_MAX) throw refused(raw, "the reference is too long");
133	        return new Line(person, new BigDecimal(amount), date, note, ref);
134	    }
135	
136	    private static ResponseStatusException refused(String line, String why) {
137	        return new ResponseStatusException(HttpStatus.CONFLICT, "Line \"" + line + "\": " + why);
138	    }
