170	/**
171	 * The claim templates on a sheet, and claims added from them; a claim added from a template answers with the
172	 * person it belongs to. The signed-in user's name comes in the {@code X-User} header.
173	 */
174	@RestController
175	@RequestMapping("/api/sheets/{sheetId}")
176	@Validated
177	public class ClaimTemplateController {
178	
179	    /** A template to save: a name (blank is refused), an amount with up to two decimals and a note. */
180	    public record TemplateForm(@Size(max = 1000) String name,
181	            @NotNull @Pattern(regexp = "\\d{1,12}(\\.\\d{1,2})?") String amount, @Size(max = 500) String note) {
182	    }
183	
184	    /** A template on the sheet; its amount with two decimals. */
185	    public record TemplateView(String name, String amount, String note) {
186	
187	        static TemplateView of(ClaimTemplate t) {
188	            return new TemplateView(t.getName(), t.getAmount().setScale(2, RoundingMode.HALF_UP).toPlainString(),
189	                    t.getNote());
190	        }
191	    }
192	
193	    /** The name of the template a claim is added from. */
194	    public record FromTemplateForm(@NotBlank @Size(max = 1000) String name) {
195	    }
196	
197	    public record Refusal(String message) {
198	    }
199	
200	    private final ClaimTemplates templates;
201	    private final ClaimService claims;
202	    private final PersonService people;
203	    private final RateService rates;
204	    private final StatementService statements;
205	
206	    public ClaimTemplateController(ClaimTemplates templates, ClaimService claims, PersonService people,
207	            RateService rates, StatementService statements) {
208	        this.templates = templates;
209	        this.claims = claims;
210	        this.people = people;
211	        this.rates = rates;
212	        this.statements = statements;
213	    }
214	
215	    @GetMapping("/claim-templates")
216	    public List<TemplateView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
217	        return templates.list(sheetId.trim()).stream().map(TemplateView::of).toList();
218	    }
219	
220	    /** Save a template, replacing the one of its name; answers with every template on the sheet. */
221	    @PostMapping("/claim-templates")
222	    public List<TemplateView> save(@PathVariable @NotBlank @Size(max = 100) String sheetId,
223	            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody TemplateForm form) {
224	        String sheet = sheetId.trim();
225	        templates.save(sheet, user.trim(), form.name(), new BigDecimal(form.amount()), form.note());
226	        return list(sheet);
227	    }
228	
229	    /** Add a DRAFT claim for a person from a template, by the claim form's rules. */
230	    @PostMapping("/people/{personId}/claims/from-template")
231	    public PersonView addClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
232	            @PathVariable long personId, @RequestHeader("X-User") @NotBlank String user,
233	            @Valid @RequestBody FromTemplateForm form) {
234	        String sheet = sheetId.trim();
235	        long id = templates.addClaim(sheet, user.trim(), personId, form.name());
236	        Person person = people.get(sheet, id);
237	        return PersonView.of(person, claims.forPerson(sheet, id), rates.table(sheet),
238	                statements.forPerson(sheet, id), people.patrons(sheet, id), people.clashing(sheet, person),
239	                people.snapshots(sheet, id));
240	    }
241	
242	    @ExceptionHandler(ClaimTemplateRefused.class)
243	    public ResponseEntity<Refusal> refused(ClaimTemplateRefused e) {
244	        return ResponseEntity.status(HttpStatus.CONFLICT).body(new Refusal(e.getMessage()));
245	    }
246	
247	    /** A claim due by a date inside a closed period: refused, nothing changed. */
248	    @ExceptionHandler(ClosedPeriodRefused.class)
249	    public ResponseEntity<Refusal> closed(ClosedPeriodRefused e) {
250	        return ResponseEntity.status(HttpStatus.CONFLICT).body(new Refusal(e.getMessage()));
251	    }
252	
253	    /** Another user saved a new template of the same name at the same moment: this one is refused. */
254	    @ExceptionHandler(DataIntegrityViolationException.class)
255	    @ResponseStatus(HttpStatus.CONFLICT)
256	    public void taken() {
257	    }
258	}

