  3	import java.math.BigDecimal;
  4	import java.time.LocalDate;
  5	import java.time.temporal.ChronoUnit;
  6	import java.util.List;
  7	import java.util.Objects;
  8	import net.officefloor.hq.app.rate.Grades;
  9	import net.officefloor.hq.app.rate.RateService;
 10	import net.officefloor.hq.app.rate.RateTable;
 11	
 12	/** The due figures of claims and the due-total of a person's claims. */
 13	public final class Dues {
 14	
 15	    private Dues() {
 16	    }
 17	
 18	    /**
 19	     * A claim's due: once settled, the due fixed then (its late charge frozen in); while bound by a statement
 20	     * to its figure as shown, that figure (its late charge bound in); a correction, its
 21	     * {@link #base} figure (no floor, no late charge); otherwise the greater of the floor in force on its date
 22	     * and its {@link #base} figure (the floored figure) plus, while overdue and not waived, its
 23	     * {@link RateTable#lateCharge late charge} on that floored figure. Null when there is none.
 24	     */
 25	    public static BigDecimal figure(Claim claim, Grades grades, RateTable rates) {
 26	        if (claim.getSettledDue() != null) {
 27	            return claim.getSettledDue();
 28	        }
 29	        if (bound(claim) && claim.isStatedAsShown()) {
 30	            return claim.getStatedDue();
 31	        }
 32	        BigDecimal base = base(claim, grades, rates);
 33	        if (base == null || claim.isCorrection()) {
 34	            return base;
 35	        }
 36	        BigDecimal floored = rates.floored(base, claim.getDate());
 37	        return overdue(claim, grades, rates) && !claim.isWaived()
 38	                ? floored.add(rates.lateCharge(floored, graceBy(claim, grades, rates), claim.getRoundsBy()))
 39	                : floored;
 40	    }
 41	
 42	    /**
 43	     * A claim's figure before any late charge or floor: while bound by a statement from before statements
 44	     * bound the figure as shown, the figure bound then; otherwise its {@link #rateFigure rate figure}. Null
 45	     * when there is none.
 46	     */
 47	    public static BigDecimal base(Claim claim, Grades grades, RateTable rates) {
 48	        if (bound(claim) && !claim.isStatedAsShown()) {
 49	            return claim.getStatedDue();
 50	        }
 51	        return rateFigure(claim, grades, rates);
 52	    }
 53	
 54	    /**
 55	     * The amount at the rate in force on the claim's date for its person's grade in force then (a forward-only
 56	     * rate only once the claim was added after it was saved), rounded by
 57	     * its date (a correction by the date its rounding goes by), see {@link RateTable#rounding}; no floor. Null when no rate is.
 58	     */
 59	    private static BigDecimal rateFigure(Claim claim, Grades grades, RateTable rates) {
 60	        String grade = grades.on(claim.getDate());
 61	        return claim.isCorrection() ? RateService.due(claim.getAmount(), rates.on(grade, claim.getDate(), claim.getId()),
 62	                rates.rounding(claim.getRoundsBy()))
 63	                : rates.figure(claim.getAmount(), grade, claim.getDate(), claim.getId());
 64	    }
 65	
 66	    /**
 67	     * The figure the claim would have today as an OPEN claim bound by no statement: its rate figure held up to
 68	     * the floor in force on its date, plus the late charge it has today on that floored figure (none once waived)
 69	     * when its due-by plus its grace has passed; a correction has neither floor nor late charge. Null when there is none. Re-settling a claim
 70	     * fixes its due at this figure.
 71	     */
 72	    public static BigDecimal asOpen(Claim claim, Grades grades, RateTable rates) {
 73	        BigDecimal base = rateFigure(claim, grades, rates);
 74	        if (base == null || claim.isCorrection()) {
 75	            return base;
 76	        }
 77	        LocalDate graceBy = graceBy(claim, grades, rates);
 78	        BigDecimal floored = rates.floored(base, claim.getDate());
 79	        return graceBy.isBefore(rates.today()) && !claim.isWaived()
 80	                ? floored.add(rates.lateCharge(floored, graceBy, claim.getRoundsBy()))
 81	                : floored;
 82	    }
 83	
 84	    /** Whether a statement binds the claim's figure: it is stated (whatever its status, PENDING included). */
 85	    public static boolean bound(Claim claim) {
 86	        return claim.isStated();
 87	    }
 88	
 89	    /**
 90	     * Whether the claim is late in review: REVIEW, with the sheet's review SLA set, and its review day (the
 91	     * sheet's today when it went to REVIEW) plus the SLA days before the sheet's today.
 92	     */
 93	    public static boolean reviewLate(Claim claim, RateTable rates) {
 94	        Integer sla = rates.settings().reviewSla();
 95	        return claim.getStatus() == ClaimStatus.REVIEW && sla != null && claim.getReviewOn() != null
 96	                && claim.getReviewOn().plusDays(sla).isBefore(rates.today());
 97	    }
 98	
 99	    /**
100	     * Whether the claim is overdue: OPEN or PENDING, not {@link #deferred deferred}, and due by a date before
101	     * the sheet's today (its due-by, fixed when it was added, plus its {@link #graceBy grace}).
102	     */
103	    public static boolean overdue(Claim claim, Grades grades, RateTable rates) {
104	        return claim.getStatus().unpaid() && !deferred(claim, rates.today())
105	                && graceBy(claim, grades, rates).isBefore(rates.today());
106	    }
107	
108	    /**
109	     * The date a claim's overdue and late charge count from: its due-by plus the grace days in force on its
110	     * date for its person's grade in force then (none: its due-by). The due-by shown is unchanged.
111	     */
112	    public static LocalDate graceBy(Claim claim, Grades grades, RateTable rates) {
113	        return claim.getDueBy().plusDays(rates.settings().grace(grades.on(claim.getDate()), claim.getDate()));
114	    }
115	
116	    /** Whether the claim is deferred on the given today: OPEN and deferred until a date after it. */
117	    public static boolean deferred(Claim claim, LocalDate today) {
118	        return claim.getStatus() == ClaimStatus.OPEN && claim.getDeferredUntil() != null
119	                && today.isBefore(claim.getDeferredUntil());
120	    }
121	
122	    /** The overdue claims that count, see {@link #overdue} and {@link #counts}. */
123	    public static List<Claim> overdue(List<Claim> claims, Grades grades, RateTable rates, Holds holds) {
124	        return claims.stream().filter(c -> counts(c, holds, rates.today()) && overdue(c, grades, rates)).toList();
125	    }
126	
127	    /** The sum of the due figures of the claims given (0.00 with none); a claim with none is skipped. */
128	    public static BigDecimal sum(Grades grades, List<Claim> claims, RateTable rates) {
129	        return claims.stream().map(c -> figure(c, grades, rates)).filter(Objects::nonNull)
130	                .reduce(BigDecimal.ZERO, BigDecimal::add);
131	    }
132	
133	    /** Whether the claim's figure is kept whatever the rates: fixed by settling or bound by a statement. */
134	    private static boolean kept(Claim claim) {
135	        return claim.getSettledDue() != null || (bound(claim) && claim.getStatedDue() != null);
136	    }
137	
138	    /**
139	     * Whether the claim counts in the live totals on the sheet's today: OPEN, PENDING and SETTLED claims do,
140	     * held ones included, except that an OPEN or PENDING claim of a person whose retirement date that today has
141	     * reached counts in none, unless a statement binds it, and a claim {@link #deferred deferred} on that today counts in none.
142	     */
143	    public static boolean counts(Claim claim, Holds holds, LocalDate today) {
144	        return claim.getStatus().counts() && !deferred(claim, today) && !leftOut(claim, holds, today);
145	    }
146	
147	    /**
148	     * A person's claimed: the sum of the amounts of the OPEN, PENDING and SETTLED claims, leaving out the claims
149	     * that correct another, a claim {@link #deferred deferred} on the sheet's today and an unbound OPEN or PENDING
150	     * claim once that today has reached the person's retirement date. A hold (the person's or the claim's own)
151	     * leaves a claim in claimed and in every total.
152	     */
153	    public static BigDecimal claimed(List<Claim> claims, Holds holds, LocalDate today) {
154	        return claims.stream().filter(c -> c.getCorrects() == null && c.getStatus().counts() && !deferred(c, today)
155	                && !retiredOut(c, holds, today)).map(Claim::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
156	    }
157	
158	    /** Whether the person's retirement leaves the claim out: unbound, OPEN or PENDING, and that today has reached it. */
159	    private static boolean retiredOut(Claim claim, Holds holds, LocalDate today) {
160	        return !bound(claim) && claim.getStatus().unpaid() && holds.retiredOn(today);
161	    }
162	
163	    /**
164	     * Whether the person's retirement leaves the claim out of the live totals (see {@link #retiredOut}). A hold
165	     * (the person's or the claim's own) leaves out none: it only takes the person's cut of a pool.
166	     */
167	    private static boolean leftOut(Claim claim, Holds holds, LocalDate today) {
168	        return retiredOut(claim, holds, today);
169	    }
170	
171	    /**
172	     * Whether the person is active on the sheet's today: they have an OPEN or PENDING claim that counts (see
173	     * {@link #counts}) dated within the 30 days up to and including that today.
174	     */
175	    public static boolean active(List<Claim> claims, Holds holds, LocalDate today) {
176	        LocalDate from = today.minusDays(29);
177	        return claims.stream().anyMatch(c -> (c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
178	                && counts(c, holds, today) && !c.getDate().isBefore(from) && !c.getDate().isAfter(today));
179	    }
180	
181	    /**
182	     * The sum of the due figures of the OPEN and PENDING claims that count (see {@link #counts}) whose age on
183	     * the sheet's today (the days from the claim's date; a claim dated after that today is aged 0) is from
184	     * {@code fromDays} to {@code toDays} inclusive (0.00 with none); a claim with no figure is skipped.
185	     */
186	    public static BigDecimal aged(Grades grades, List<Claim> claims, RateTable rates, Holds holds, long fromDays,
187	            long toDays) {
188	        LocalDate today = rates.today();
189	        return sum(grades, claims.stream().filter(c -> c.getStatus().unpaid() && counts(c, holds, today))
190	                .filter(c -> {
191	                    long age = Math.max(0, ChronoUnit.DAYS.between(c.getDate(), today));
192	                    return age >= fromDays && age <= toDays;
193	                }).toList(), rates);
194	    }
195	
196	    /**
197	     * The sum of the settled figures of the SETTLED claims dated within the 90 days up to and including the
198	     * sheet's today, each at the figure frozen when it was settled (0.00 with none); one with none is skipped.
199	     */
200	    public static BigDecimal recentSettled(List<Claim> claims, LocalDate today) {
201	        LocalDate from = today.minusDays(89);
202	        return claims.stream().filter(c -> c.getStatus() == ClaimStatus.SETTLED && c.getSettledDue() != null
203	                && !c.getDate().isBefore(from) && !c.getDate().isAfter(today)).map(Claim::getSettledDue)
204	                .reduce(BigDecimal.ZERO, BigDecimal::add);
205	    }
206	
207	    /**
208	     * The status the claim had at the end of the given day, as its status log records it (each line on the
209	     * sheet's today then); null when it was added after that day.
210	     */
211	    public static ClaimStatus statusAsOf(Claim claim, LocalDate day) {
212	        ClaimStatus status = null;
213	        for (ClaimLogLine line : claim.getLog()) {
214	            if (!line.getOn().isAfter(day)) {
215	                status = line.getStatus();
216	            }
217	        }
218	        return status;
219	    }
220	
221	    /**
222	     * Whether the claim counts in a period ending on {@code end}: its status at the end of that day (see
223	     * {@link #statusAsOf}) is OPEN, PENDING or SETTLED, and it is not deferred on the
224	     * sheet's today, as in {@link #counts}; so too by a retirement reached on that today.
225	     */
226	    public static boolean countsAsOf(Claim claim, Holds holds, LocalDate today, LocalDate end) {
227	        ClaimStatus then = statusAsOf(claim, end);
228	        return then != null && then.counts() && !deferred(claim, today) && !leftOut(claim, holds, today);
229	    }
230	
231	    /**
232	     * A person's due-total (see {@link #total}); a person not on hold.
233	     */
234	    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates) {
235	        return total(grades, claims, rates, Holds.NONE);
236	    }
237	
238	    /**
239	     * A person's due-total: their {@link #uncapped} sum held to the sheet's cap, see {@link RateTable#capped}.
240	     * Null (n/a) when the sum is.
241	     */
242	    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
243	        return rates.capped(uncapped(grades, claims, rates, holds));
244	    }
245	
246	    /** What a person's {@link #uncapped} sum is above the sheet's cap: 0.00 when it is not, or is n/a. */
247	    public static BigDecimal excess(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
248	        return rates.excess(uncapped(grades, claims, rates, holds));
249	    }
250	
251	    /**
252	     * The sum of the due figures of the claims that count (0.00 with none), see {@link #counts}. Null (n/a)
253	     * when the grade in force on the sheet's today has no rate on it, unless a claim that counts has a
254	     * figure not made by that grade (kept, or at the rate for another grade in force on its date): then it
255	     * is the sum of the figures there are; so too when that grade's rate has ended by the sheet's today and
256	     * a claim that counts has a figure.
257	     */
258	    public static BigDecimal uncapped(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
259	        List<Claim> counting = claims.stream().filter(c -> counts(c, holds, rates.today())).toList();
260	        String current = grades.on(rates.today());
261	        boolean ended = rates.ended(current, rates.today());
262	        boolean shown = rates.current(current) != null || counting.stream().anyMatch(c -> kept(c)
263	                || ((ended || !current.equals(grades.on(c.getDate()))) && figure(c, grades, rates) != null));
264	        return shown ? counting.stream().map(c -> figure(c, grades, rates))
265	                .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add) : null;
266	    }
267	
268	    /**
269	     * The settled part of a person's {@link #uncapped} sum: the due figures of their SETTLED claims that count,
270	     * each at its frozen figure (corrections included); a claim with no figure is skipped.
271	     */
272	    public static BigDecimal settledTotal(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
273	        return part(grades, claims, rates, holds, true);
274	    }
275	
276	    /**
277	     * The open part of a person's {@link #uncapped} sum: the due figures of their OPEN and PENDING claims that
278	     * count (a deferred or retired-and-left-out claim does not); a claim with no figure is skipped.
279	     */
280	    public static BigDecimal openTotal(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
281	        return part(grades, claims, rates, holds, false);
282	    }
283	
284	    private static BigDecimal part(Grades grades, List<Claim> claims, RateTable rates, Holds holds, boolean settled) {
285	        return sum(grades, claims.stream().filter(c -> counts(c, holds, rates.today())
286	                && (c.getStatus() == ClaimStatus.SETTLED) == settled).toList(), rates);
287	    }
288	}

