  1	package net.officefloor.hq.app.claim;
  2	/**
  3	 * A claim a person makes: an amount (two decimals), a date, a note and a status. A negative amount is a
  4	 * correction, naming the number of the SETTLED claim of the same person it corrects.
  5	 */
  6	public class Claim {
  7	    private Long id;
  8	    private String sheetId;
  9	    private Long personId;
 10	    private BigDecimal amount;
 11	    private LocalDate date;
 12	    private String note;
 13	    @Enumerated(EnumType.STRING)
 14	    private ClaimStatus status = ClaimStatus.DRAFT;
 15	    /** The number the claim got when opened; null while a draft; a voided claim keeps it. */
 16	    private Integer number;
 17	    /** The fiscal year (FY<year>) a sheet-wide number counts in, shown <FY>-<n>; null for a number given before. */
 18	    private String fiscalYear;
 19	    /** The sequence a period-numbered claim counts in ('P<period id>', or 'X' for no period); null otherwise. */
 20	    private String periodSequence;
 21	    /** The claim's place in its period sequence; null for a sheet-wide number. */
 22	    private Integer periodSeqNumber;
 23	    /** The number as shown for a period-numbered claim (<period name>-<n>, or X-<n>); null otherwise. */
 24	    private String periodNumber;
 25	    /** The user who opened the claim; null while a draft and once voided. */
 26	    private String openedBy;
 27	    /** The bulk settle batch that settled the claim (to SETTLED or PENDING); null when settled one at a time or never. */
 28	    private Integer settleBatch;
 29	    /** The user who last edited the claim; null while never edited. */
 30	    private String editedBy;
 31	    /** The due fixed when the claim was settled; null while not settled or when there was no rate. */
 32	    private BigDecimal settledDue;
 33	    /** Whether the person's last statement bound the claim to statedDue. */
 34	    private boolean stated;
 35	    /** The figure the last statement bound the claim to; null while unbound or when it had none. */
 36	    private BigDecimal statedDue;
 37	    /**
 38	     * Whether statedDue is the figure as shown, late charge included; false for a claim bound before
 39	     * statements bound that, whose statedDue is its figure without its late charge.
 40	     */
 41	    private boolean statedAsShown;
 42	    /** The number of the claim a correction corrects; null for any other claim. */
 43	    private String corrects;
 44	    /** The date of the claim a correction corrects, which its rounding goes by; null for any other claim. */
 45	    private LocalDate correctsDate;
 46	    /**
 47	     * The date the claim is due by, fixed when it was added: the terms-th business day after its date, by the
 48	     * terms then of its person's grade on its date and the holidays on the sheet then. A holiday added later
 49	     * fixes it again over the holidays then, with the same terms (see {@link #terms}).
 50	     */
 51	    private LocalDate dueBy;
 52	    /** The terms (in business days) the claim's due-by was fixed with. */
 53	    private int terms;
 54	    /** The date the claim is deferred until; null when it was never deferred. See {@link Dues#deferred}. */
 55	    private LocalDate deferredUntil;
 56	    /** The last sheet's today a reminder was written for the claim; null when it was never reminded. */
 57	    private LocalDate remindedOn;
 58	    /** The sheet's today when the claim last went to REVIEW; null when it never did. */
 59	    private LocalDate reviewOn;
 60	    /** Whether a reminder ever escalated the claim; a claim is escalated at most once. */
 61	    private boolean escalated;
 62	    /** Whether a steward waived the claim's late charge; a waived claim bears none from then on. */
 63	    private boolean waived;
 64	    /** Whether the claim is held: it still counts in every total. */
 65	    private boolean held;
 66	    /** How many proofs the claim has; it starts at 0. */
 67	    private int proofs;
 68	    /** How many of the claim's proofs are photos; the rest are receipts. */
 69	    private int proofPhotos;
 70	    /** The number (as shown) of the claim this one was split off; null for any claim not split off another. */
 71	    private String splitFrom;
 72	    /** The claim's external reference, unique on its sheet without regard to case; null when it has none. */
 73	    private String ref;
 74	    /** The claim's tags, sorted and comma separated; "" when it has none. */
 75	    private String tags = "";
 76	    /** The reason from the sheet's list the claim was voided with; null when it is not VOID or was voided without one. */
 77	    private String voidReason;
 78	    /** Whether the claim was added while a soft-closed period contained its due-by. */
 79	    private boolean lateEntry;
 80	    /**
 81	     * The user whose open editor locks the claim for everyone else, until it is saved or cancelled or the
 82	     * sheet's today changes; null when no editor holds it.
 83	     */
 84	    private String lockedBy;
 85	    /** The claim's place in its person's list, newest first; the store takes it on adding and reassigning. */
 86	    private Long listed;
 87	    /** The claim's status log: one line per status it has had, oldest first. */
 88	    @ElementCollection(fetch = FetchType.EAGER)
 89	    @CollectionTable(name = "claim_log", joinColumns = @JoinColumn(name = "claim_id"))
 90	    @OrderColumn(name = "seq")
 91	    private List<ClaimLogLine> log = new ArrayList<>();
 92	    /** The claim's comments, oldest first. */
 93	    @ElementCollection(fetch = FetchType.EAGER)
 94	    @CollectionTable(name = "claim_comment", joinColumns = @JoinColumn(name = "claim_id"))
 95	    @OrderColumn(name = "seq")
 96	    private List<ClaimComment> comments = new ArrayList<>();
 97	    /** The claim's lines, in the order they were added; with any, its amount is theirs added up. */
 98	    @ElementCollection(fetch = FetchType.EAGER)
 99	    @CollectionTable(name = "claim_line", joinColumns = @JoinColumn(name = "claim_id"))
100	    @OrderColumn(name = "seq")
101	    private List<ClaimLine> lines = new ArrayList<>();
102	    protected Claim() {
103	    }
104	    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, String corrects) {
105	        this.corrects = corrects;
106	        this.sheetId = sheetId;
107	        this.personId = personId;
108	        this.amount = amount;
109	        this.date = date;
110	        this.note = note;
111	    }
112	    public Long getId() {
113	        return id;
114	    }
115	    public String getSheetId() {
116	        return sheetId;
117	    }
118	    /**
119	     * The claim as it arrives on another sheet for the person there: its status, dates, note, tags, frozen
120	     * figures, log, comments and lines; unnumbered (to be given the other sheet's next), released from any figure a
121	     * statement bound, without its reference, settle batch or editor lock.
122	     */
123	    public Claim arriving(String sheetId, Long personId) {
124	        Claim arrived = new Claim(sheetId, personId, amount, date, note, corrects);
125	        arrived.status = status;
126	        arrived.openedBy = openedBy;
127	        arrived.editedBy = editedBy;
128	        arrived.settledDue = settledDue;
129	        arrived.correctsDate = correctsDate;
130	        arrived.dueBy = dueBy;
131	        arrived.terms = terms;
132	        arrived.deferredUntil = deferredUntil;
133	        arrived.remindedOn = remindedOn;
134	        arrived.escalated = escalated;
135	        arrived.waived = waived;
136	        arrived.held = held;
137	        arrived.reviewOn = reviewOn;
138	        arrived.proofs = proofs;
139	        arrived.proofPhotos = proofPhotos;
140	        arrived.splitFrom = splitFrom;
141	        arrived.tags = tags;
142	        arrived.voidReason = voidReason;
143	        arrived.lateEntry = lateEntry;
144	        log.forEach(l -> arrived.log.add(new ClaimLogLine(l.getStatus(), l.getBy(), l.getOn(), l.getDue())));
145	        comments.forEach(c -> arrived.comments.add(new ClaimComment(c.getBy(), c.getOn(), c.getText())));
146	        lines.forEach(l -> arrived.lines.add(new ClaimLine(l.getLabel(), l.getQty(), l.getUnit())));
147	        return arrived;
148	    }
149	    /**
150	     * The claim as copied onto a clone of its sheet for the person there: as {@link #arriving}, keeping its
151	     * reference too.
152	     */
153	    /**
154	     * A copy rebuilt from a written-down sheet (never saved) carries the id the claim has in the store, so the
155	     * forward-only rates saved after it was added are left out of its figures as they are for the claim itself.
156	     */
157	    public Claim restoredAs(Long id) {
158	        this.id = id;
159	        return this;
160	    }
161	    public Claim cloned(String sheetId, Long personId) {
162	        Claim copy = arriving(sheetId, personId);
163	        copy.ref = ref;
164	        return copy;
165	    }
166	    public Long getListed() {
167	        return listed;
168	    }
169	    public Long getPersonId() {
170	        return personId;
171	    }
172	    public void setPersonId(Long personId) {
173	        this.personId = personId;
174	    }
175	    public BigDecimal getAmount() {
176	        return amount;
177	    }
178	    public void setAmount(BigDecimal amount) {
179	        this.amount = amount;
180	    }
181	    public LocalDate getDate() {
182	        return date;
183	    }
184	    public void setDate(LocalDate date) {
185	        this.date = date;
186	    }
187	    public LocalDate getDueBy() {
188	        return dueBy;
189	    }
190	    public void setDueBy(LocalDate dueBy) {
191	        this.dueBy = dueBy;
192	    }
193	    public int getTerms() {
194	        return terms;
195	    }
196	    public void setTerms(int terms) {
197	        this.terms = terms;
198	    }
199	    public String getLockedBy() {
200	        return lockedBy;
201	    }
202	    public void setLockedBy(String lockedBy) {
203	        this.lockedBy = lockedBy;
204	    }
205	    public LocalDate getDeferredUntil() {
206	        return deferredUntil;
207	    }
208	    public void setDeferredUntil(LocalDate deferredUntil) {
209	        this.deferredUntil = deferredUntil;
210	    }
211	    public LocalDate getRemindedOn() {
212	        return remindedOn;
213	    }
214	    public void setRemindedOn(LocalDate remindedOn) {
215	        this.remindedOn = remindedOn;
216	    }
217	    public LocalDate getReviewOn() {
218	        return reviewOn;
219	    }
220	    public void setReviewOn(LocalDate reviewOn) {
221	        this.reviewOn = reviewOn;
222	    }
223	    public boolean isWaived() {
224	        return waived;
225	    }
226	    public void setWaived(boolean waived) {
227	        this.waived = waived;
228	    }
229	    public boolean isHeld() {
230	        return held;
231	    }
232	    public void setHeld(boolean held) {
233	        this.held = held;
234	    }
235	    public boolean isEscalated() {
236	        return escalated;
237	    }
238	    public void setEscalated(boolean escalated) {
239	        this.escalated = escalated;
240	    }
241	    public int getProofs() {
242	        return proofs;
243	    }
244	    /** How many of the claim's proofs are of the kind (receipt or photo). */
245	    public int getProofs(String kind) {
246	        return PHOTO.equals(kind) ? proofPhotos : RECEIPT.equals(kind) ? proofs - proofPhotos : 0;
247	    }
248	    /** A proof kind: a receipt, the kind of a proof added with none chosen. */
249	    public static final String RECEIPT = "receipt";
250	    /** A proof kind: a photo. */
251	    public static final String PHOTO = "photo";
252	    /** Add a proof of the kind (receipt or photo): the proofs count is raised by one. */
253	    public void addProof(String kind) {
254	        proofs++;
255	        if (PHOTO.equals(kind)) {
256	            proofPhotos++;
257	        }
258	    }
259	    public String getNote() {
260	        return note;
261	    }
262	    public void setNote(String note) {
263	        this.note = note;
264	    }
265	    public String getCorrects() {
266	        return corrects;
267	    }
268	    public void setCorrects(String corrects) {
269	        this.corrects = corrects;
270	    }
271	    public LocalDate getCorrectsDate() {
272	        return correctsDate;
273	    }
274	    public void setCorrectsDate(LocalDate correctsDate) {
275	        this.correctsDate = correctsDate;
276	    }
277	    /** The date the claim's rounding goes by: a correction's is the date of the claim it corrects. */
278	    public LocalDate getRoundsBy() {
279	        return correctsDate != null ? correctsDate : date;
280	    }
281	    /** Whether the claim is a correction: its amount is negative. */
282	    public boolean isCorrection() {
283	        return amount.signum() < 0;
284	    }
285	    public ClaimStatus getStatus() {
286	        return status;
287	    }
288	    public void setStatus(ClaimStatus status) {
289	        this.status = status;
290	    }
291	    public List<ClaimLogLine> getLog() {
292	        return List.copyOf(log);
293	    }
294	    /** Log the status the claim has now, by a user on a date, with its due then. */
295	    public void logStatus(String by, LocalDate on, BigDecimal due) {
296	        log.add(new ClaimLogLine(status, by, on, due));
297	    }
298	    public List<ClaimComment> getComments() {
299	        return List.copyOf(comments);
300	    }
301	    /** Add a comment by a user on a date. */
302	    public void comment(String by, LocalDate on, String text) {
303	        comments.add(new ClaimComment(by, on, text));
304	    }
305	    public List<ClaimLine> getLines() {
306	        return List.copyOf(lines);
307	    }
308	    /** Whether the claim has lines, which its amount is then the sum of. */
309	    public boolean hasLines() {
310	        return !lines.isEmpty();
311	    }
312	    /** Add a line; the claim's amount becomes its lines' amounts added up. */
313	    public void addLine(String label, int qty, BigDecimal unit) {
