  1	import { HttpContextToken, HttpInterceptorFn } from '@angular/common/http';
  2	import { inject } from '@angular/core';
  3	import { Session } from './session';
  4	
  5	/** Marks a sheet request that reads the live sheet whatever date the screen shows it as of. */
  6	export const LIVE = new HttpContextToken<boolean>(() => false);
  7	
  8	/** Names the date the screen shows the sheet as of (X-As-Of) on every sheet request while one is set. */
  9	export const asOfInterceptor: HttpInterceptorFn = (req, next) => {
 10	  const asOf = inject(Session).asOf();
 11	  if (asOf === null || req.context.get(LIVE) || !req.url.startsWith('/api/sheets/')) return next(req);
 12	  return next(req.clone({ setHeaders: { 'X-As-Of': asOf } }));
 13	};
 14	import { Pipe, PipeTransform, inject } from '@angular/core';
 15	import { Session } from './session';
 16	
 17	/** A figure as the server sends it: digits, a dot, two decimals. */
 18	const FIGURE = /^(-?)(\d+)\.(\d{2})$/;
 19	
 20	/**
 21	 * Shows a figure (an amount, total, rate, share or cut with two decimals) in the signed-in user's locale:
 22	 * under de as 1.234,56, under en as it comes. Anything that is not such a figure is shown as it is.
 23	 * Impure, as it reads the user's locale, which may change while the value does not.
 24	 */
 25	@Pipe({ name: 'figure', pure: false })
 26	export class FigurePipe implements PipeTransform {
 27	  private readonly session = inject(Session);
 28	
 29	  transform<T>(value: T): T | string {
 30	    return formatFigure(value, this.session.locale());
 31	  }
 32	}
 33	
 34	export function formatFigure<T>(value: T, locale: string): T | string {
 35	  if (locale !== 'de' || typeof value !== 'string') return value;
 36	  const m = FIGURE.exec(value);
 37	  if (!m) return value;
 38	  return `${m[1]}${m[2].replace(/\B(?=(\d{3})+$)/g, '.')},${m[3]}`;
 39	}
 40	import { HttpClient } from '@angular/common/http';
 41	import { Injectable, computed, inject, signal } from '@angular/core';
 42	import { firstValueFrom } from 'rxjs';
 43	
 44	/** The locales a user may choose; en unless chosen. */
 45	export const LOCALES = ['en', 'de'] as const;
 46	export type Locale = (typeof LOCALES)[number];
