 57	@Injectable({ providedIn: 'root' })
 58	export class Session {
 59	  private readonly http = inject(HttpClient);
 60	
 61	  readonly user = signal<string | null>(null);
 62	  /** The signed-in user's locale, saved per user: how the screen shows them figures. */
 63	  readonly locale = signal<Locale>('en');
 64	  readonly sheet = signal<string | null>(null);
