 72	  /** The active sheet's today (yyyy-mm-dd): every date the screen decides on or defaults to; the as-of date while set. */
 73	  readonly today = computed(() => this.asOf() ?? this.sheetToday());
 74	  /** Whether the active sheet is archived: it stays visible and every change to it is refused. */
 75	  readonly archived = signal(false);
 76	  /** The id of the active sheet's parent sheet, as it stands; null when it has none. */
 77	  readonly parent = signal<string | null>(null);
 78	  /** The id of the last clone of the active sheet made from this screen; null before any. */
 79	  readonly clonedTo = signal<string | null>(null);
 80	  /** Bumped on every sheet load, so what is shown for the sheet is re-read even for the same id. */
 81	  readonly loads = signal(0);
