 83	  async signIn(name: string): Promise<void> {
 84	    const res = await firstValueFrom(this.http.post<{ name: string; locale: Locale }>('/api/signin', { name }));
 85	    this.sheet.set(null);
 86	    this.sheetToday.set(null);
 87	    this.asOf.set(null);
 88	    this.archived.set(false);
 89	    this.parent.set(null);
 90	    this.clonedTo.set(null);
 91	    this.loads.update((n) => n + 1);
 92	    this.locale.set(res.locale);
 93	    this.user.set(res.name);
 94	  }
 95	
 96	  /** Save the signed-in user's locale. */
 97	  async setLocale(locale: Locale): Promise<void> {
 98	    const res = await firstValueFrom(
 99	      this.http.put<{ locale: Locale }>('/api/me/locale', { locale }, {
100	        headers: { 'X-User': this.user() ?? '' },
101	      }),
102	    );
103	    this.locale.set(res.locale);
104	  }
105	
106	  async loadSheet(id: string): Promise<void> {
107	    const res = await firstValueFrom(
108	      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
109	        headers: { 'X-User': this.user() ?? '' },
110	      }),
111	    );
112	    this.sheet.set(res.id);
113	    this.sheetToday.set(res.today);
114	    this.archived.set(res.archived);
115	    this.parent.set(res.parent);
116	    this.clonedTo.set(null);
117	    if (this.asOf() !== null) await this.readShown(res.id);
118	    this.loads.update((n) => n + 1);
119	  }
120	
121	  /** Show the active sheet as of a date (yyyy-mm-dd), or as it stands (null): everything shown is re-read. */
122	  async setAsOf(date: string | null): Promise<void> {
123	    this.asOf.set(date);
124	    const id = this.sheet();
125	    if (id) await this.readShown(id);
126	    this.loads.update((n) => n + 1);
127	  }
128	
129	  /** Re-read whether the sheet is archived, as it is shown (as of the as-of date while one is set). */
130	  private async readShown(id: string): Promise<void> {
131	    const res = await firstValueFrom(this.http.get<SheetView>(`/api/sheets/${encodeURIComponent(id)}`));
132	    if (this.sheet() === res.id) this.archived.set(res.archived);
133	  }
134	
135	  async setToday(today: string): Promise<void> {
136	    const id = this.sheet();
137	    if (!id) return;
138	    const res = await firstValueFrom(
139	      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
140	        headers: { 'X-User': this.user() ?? '' },
141	      }),
142	    );
143	    if (this.sheet() === res.id) this.sheetToday.set(res.today);
144	  }
145	
146	  async archive(): Promise<void> {
147	    const id = this.sheet();
148	    if (!id) return;
149	    const res = await firstValueFrom(
150	      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null, {
151	        headers: { 'X-User': this.user() ?? '' },
152	      }),
153	    );
154	    if (this.sheet() === res.id) this.archived.set(res.archived);
155	  }
156	
157	  /** Clone the active sheet to another id, which must never have been used. */
158	  async cloneTo(to: string): Promise<void> {
159	    const id = this.sheet();
160	    if (!id) return;
161	    await firstValueFrom(
162	      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/clone`, { to }, {
163	        headers: { 'X-User': this.user() ?? '' },
164	      }),
165	    );
166	    if (this.sheet() === id) this.clonedTo.set(to);
167	  }
