142	  protected readonly byPeriod = computed(() => {
143	    const totals = periodDueTotals(this.periods(), this.people());
144	    const previous = new Map<number, string>();
145	    const byStart = [...this.periods()].sort((a, b) => a.from.localeCompare(b.from));
146	    byStart.forEach((p, i) => {
