105	/**
106	 * Settles a selection of claims together, all or nothing, in list order: the people in the order they were
107	 * added, each person's newest claim first. Each claim is settled by the rules of settling one; if any one of
108	 * them is refused, none is settled, every one counts as refused and nothing is written. One left PENDING
109	 * (a clerk over the clerk limit) is not refused and counts as settled. A bulk settle that goes through is the
110	 * sheet's next settle batch, numbered 1, 2, ..., each claim it settled shows that number, and after the
111	 * claims' own lines a BATCH_SETTLED line records it.
112	 */
113	@Service
114	public class BulkSettleService {
115	    public record Result(int settled, int refused) {
116	    }
117	    private final ClaimService claims;
118	    private final SelectedClaims selected;
119	    private final AccessService access;
120	    private final TransactionTemplate transaction;
121	    public BulkSettleService(ClaimService claims, SelectedClaims selected, AccessService access,
122	            PlatformTransactionManager transactions) {
123	        this.access = access;
124	        this.claims = claims;
125	        this.selected = selected;
126	        this.transaction = new TransactionTemplate(transactions);
127	    }
128	    public Result settle(String sheetId, String user, Set<Long> claimIds) {
129	        if (access.isArchived(sheetId) || access.isViewer(sheetId, user)) {
130	            return new Result(0, claimIds.size()); // an archived sheet, or a viewer, changes nothing: every one refused
131	        }
132	        List<Claim> inOrder = selected.inListOrder(sheetId, claimIds);
133	        if (inOrder.size() != claimIds.size()) {
134	            return new Result(0, claimIds.size()); // a claim not on the sheet cannot be settled: every one refused
135	        }
136	        return transaction.execute(status -> {
137	            List<Long> settled = new ArrayList<>();
138	            for (Claim c : inOrder) {
139	                try {
140	                    claims.move(sheetId, user, c.getId(), ClaimStatus.SETTLED);
141	                    settled.add(c.getId());
142	                } catch (ResponseStatusException | ClosedPeriodRefused refused) {
143	                    status.setRollbackOnly(); // one refused: none is settled and nothing is written
144	                    return new Result(0, claimIds.size());
145	                }
146	            }
147	            if (!settled.isEmpty()) {
148	                claims.settleBatch(sheetId, user, settled);
149	            }
150	            return new Result(settled.size(), claimIds.size() - settled.size());
151	        });
152	    }
153	}
