385	/**
386	 * The sheet's duplicate claims: for each person, date and amount with two or more claims (VOID and DELETED
387	 * claims left out), people in list order, then by date, then by amount. It reads the store; it records nothing.
388	 */
389	@Service
390	public class DuplicateClaims {
391	    /** A person, date and amount with {@code count} claims; the amount as shown, with two decimals. */
392	    public record Duplicate(String name, LocalDate date, String amount, int count) {
393	    }
394	    private record Key(LocalDate date, BigDecimal amount) {
395	    }
396	    private static final Comparator<Key> ORDER = Comparator.comparing(Key::date)
397	            .thenComparing(Key::amount);
398	    private final ClaimRepository claims;
399	    private final PersonRepository people;
400	    public DuplicateClaims(ClaimRepository claims, PersonRepository people) {
401	        this.claims = claims;
402	        this.people = people;
403	    }
404	    @Transactional(readOnly = true)
405	    public List<Duplicate> find(String sheetId) {
406	        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
407	                .filter(c -> c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
408	                .collect(Collectors.groupingBy(Claim::getPersonId));
409	        List<Duplicate> found = new ArrayList<>();
410	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
411	            Map<Key, Integer> counts = new TreeMap<>(ORDER);
412	            for (Claim c : byPerson.getOrDefault(p.getId(), List.of())) {
413	                Key key = new Key(c.getDate(), c.getAmount().setScale(2, RoundingMode.HALF_UP));
414	                counts.merge(key, 1, Integer::sum);
415	            }
416	            counts.forEach((key, count) -> {
417	                if (count >= 2) {
418	                    found.add(new Duplicate(p.getName(), key.date(), key.amount().toPlainString(), count));
419	                }
420	            });
421	        }
422	        return found;
423	    }
424	}
