439	/**
440	 * What a candidate rate for a grade would do to the dues shown: the OPEN and PENDING claims of people on that
441	 * grade (the grade in force on the claim's date) whose due would differ if the rate applied to the grade on
442	 * every date, and the sum of the differences. A claim bound by a statement keeps its due. Nothing is saved.
443	 */
444	@Service
445	public class RatePreviewService {
446	    /** How many claims would show a different due, and the sum of new due minus current due. */
447	    public record Preview(int count, BigDecimal diff) {
448	    }
449	    private final PersonRepository people;
450	    private final ClaimRepository claims;
451	    private final RateService rates;
452	    public RatePreviewService(PersonRepository people, ClaimRepository claims, RateService rates) {
453	        this.people = people;
454	        this.claims = claims;
455	        this.rates = rates;
456	    }
457	    @Transactional(readOnly = true)
458	    public Preview preview(String sheetId, String grade, BigDecimal pct) {
459	        RateTable table = rates.table(sheetId);
460	        List<Rate> candidate = new ArrayList<>(table.rates().stream().filter(r -> !r.getGrade().equals(grade)).toList());
461	        candidate.add(new Rate(sheetId, grade, null, null, pct.setScale(2, RoundingMode.HALF_UP)));
462	        RateTable then = new RateTable(candidate, table.today(), table.settings(), table.policyDate(),
463	                table.ancestors());
464	        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
465	                .collect(Collectors.groupingBy(Claim::getPersonId));
466	        int count = 0;
467	        BigDecimal diff = BigDecimal.ZERO;
468	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
469	            for (Claim claim : byPerson.getOrDefault(person.getId(), List.of())) {
470	                if (!claim.getStatus().unpaid() || Dues.bound(claim) || !grade.equals(person.gradeOn(claim.getDate()))) {
471	                    continue;
472	                }
473	                BigDecimal now = Dues.figure(claim, person::gradeOn, table);
474	                BigDecimal next = Dues.figure(claim, person::gradeOn, then);
475	                if (!Objects.equals(now == null ? null : now.setScale(2, RoundingMode.HALF_UP),
476	                        next == null ? null : next.setScale(2, RoundingMode.HALF_UP))) {
477	                    count++;
478	                    diff = diff.add(next == null ? BigDecimal.ZERO : next).subtract(now == null ? BigDecimal.ZERO : now);
479	                }
480	            }
481	        }
482	        return new Preview(count, diff.setScale(2, RoundingMode.HALF_UP));
483	    }
484	}
