    47	/**
    48	 * Cloning a sheet to another id. Only a steward of this sheet may, and only to an id never used; anything
    49	 * else is refused. The clone gets this sheet's today, settings, roles, rates, holidays, void reasons,
    50	 * templates and tags, its people (grades, terms, contacts, aliases, holds, retirements, patrons), pools, crews,
    51	 * periods (all open) and claims (status, frozen figures, dates, notes, tags, logs and comments). Each claim
    52	 * that had a number takes the clone's next one, in the order the claims were opened (by the sheet's today
    53	 * when each was opened, then by the order they were added, person by person in list order). Statements are
    54	 * not copied: figures a statement bound are released.
    55	 */
    56	@Service
    57	public class SheetCloneService {
    58	
    59	    private final SheetRepository sheetRows;
    60	    private final SheetSettingRepository settings;
    61	    private final SheetRoleRepository roles;
    62	    private final RateRepository rates;
    63	    private final HolidayRepository holidays;
    64	    private final VoidReasonRepository voidReasons;
    65	    private final ClaimTemplateRepository templates;
    66	    private final SheetTagRepository tags;
    67	    private final PersonRepository people;
