    79	    public SheetCloneService(SheetRepository sheetRows, SheetSettingRepository settings, SheetRoleRepository roles,
    80	            RateRepository rates, HolidayRepository holidays, VoidReasonRepository voidReasons,
    81	            ClaimTemplateRepository templates, SheetTagRepository tags, PersonRepository people,
    82	            PatronRepository patrons, PoolRepository pools, PoolMemberRepository poolMembers, Crews crews,
    83	            PeriodRepository periods, ClaimRepository claims, ClaimService claimService, AccessService access,
    84	            Rollup rollup, ApplicationEventPublisher events) {
    85	        this.sheetRows = sheetRows;
    86	        this.settings = settings;
    87	        this.roles = roles;
    88	        this.rates = rates;
    89	        this.holidays = holidays;
    90	        this.voidReasons = voidReasons;
    91	        this.templates = templates;
    92	        this.tags = tags;
    93	        this.people = people;
    94	        this.patrons = patrons;
    95	        this.pools = pools;
    96	        this.poolMembers = poolMembers;
    97	        this.crews = crews;
    98	        this.periods = periods;
    99	        this.claims = claims;
   100	        this.claimService = claimService;
   101	        this.access = access;
   102	        this.rollup = rollup;
   103	        this.events = events;
   104	    }
   105	
   106	    /** Clone the sheet to the other id; refused (403) for anyone but a steward, (409) when the id was used. */
   107	    @Transactional
   108	    public Sheet cloneTo(String sheetId, String user, String toSheet) {
   109	        Sheet sheet = sheetRows.lockById(sheetId);
   110	        if (sheet == null) {
   111	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet");
   112	        }
   113	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
   114	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can clone the sheet");
   115	        }
   116	        if (toSheet.equals(sheetId) || sheetRows.existsById(toSheet)) {
   117	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet is already in use");
   118	        }
   119	        sheetRows.saveAndFlush(sheet.cloned(toSheet));
   120	
   121	        settings.findBySheetId(sheetId).stream().sorted(Comparator.comparing(SheetSetting::getId))
   122	                .forEach(s -> settings.save(new SheetSetting(toSheet, s.getKey(), s.getFromDate(), s.getValue())));
   123	        roles.findBySheetIdOrderByUserName(sheetId)
   124	                .forEach(r -> roles.save(new SheetRole(toSheet, r.getUserName(), r.getRole())));
   125	        Map<Rate, Long> forwardOnly = new HashMap<>();
   126	        rates.findBySheetId(sheetId).stream().sorted(Comparator.comparing(Rate::getId)).forEach(r -> {
   127	            Rate copy = rates.save(new Rate(toSheet, r.getGrade(), r.getFromDate(), r.getToDate(), r.getPct()));
   128	            if (r.getForwardAfter() != null) {
   129	                forwardOnly.put(copy, r.getForwardAfter());
   130	            }
   131	        });
   132	        holidays.findBySheetIdOrderByDayAsc(sheetId).forEach(h -> holidays.save(new Holiday(toSheet, h.getDay())));
   133	        voidReasons.findBySheetIdOrderByIdAsc(sheetId)
   134	                .forEach(v -> voidReasons.save(new VoidReason(toSheet, v.getReason())));
   135	        templates.findBySheetIdOrderByNameAsc(sheetId)
   136	                .forEach(t -> templates.save(new ClaimTemplate(toSheet, t.getName(), t.getAmount(), t.getNote())));
   137	        tags.findBySheetIdOrderByTagAsc(sheetId).forEach(t -> tags.save(new SheetTag(toSheet, t.getTag())));
   138	        periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().sorted(Comparator.comparing(Period::getId))
   139	                .forEach(p -> periods.save(new Period(toSheet, p.getName(), p.getFromDate(), p.getToDate(), p.getCap())));
   140	
   141	        Map<Long, Long> personIds = new HashMap<>();
   142	        List<Person> theirs = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
   143	        for (Person person : theirs) {
   144	            personIds.put(person.getId(), people.save(person.cloned(toSheet)).getId());
   145	        }
   146	        patrons.findBySheetIdOrderByIdAsc(sheetId).forEach(p -> patrons
   147	                .save(new Patron(toSheet, personIds.get(p.getPersonId()), personIds.get(p.getPatronId()))));
   148	
   149	        Map<Long, Long> poolIds = new HashMap<>();
   150	        List<Pool> theirPools = pools.findBySheetIdOrderByNameAsc(sheetId).stream()
   151	                .sorted(Comparator.comparing(Pool::getId)).toList();
   152	        for (Pool pool : theirPools) {
   153	            poolIds.put(pool.getId(), pools.save(new Pool(toSheet, pool.getName())).getId());
   154	        }
   155	        if (!poolIds.isEmpty()) {
   156	            for (PoolMember m : poolMembers.findByPoolIdInOrderByIdAsc(poolIds.keySet())) {
   157	                PoolMember copy = m.getMemberPoolId() != null
   158	                        ? PoolMember.ofPool(poolIds.get(m.getPoolId()), poolIds.get(m.getMemberPoolId()), m.getShare())
   159	                        : new PoolMember(poolIds.get(m.getPoolId()), personIds.get(m.getPersonId()), m.getShare());
   160	                poolMembers.save(copy.dated(m.getFrom(), m.getTo()));
   161	            }
   162	        }
   163	        crews.cloneTo(sheetId, toSheet, personIds);
   164	        sheetRows.flush();
   165	
   166	        // person by person in list order, each one's claims oldest listed first, so they list as they do here
   167	        Map<Long, List<Claim>> byPerson = new HashMap<>();
   168	        List<Claim> listed = new ArrayList<>(claims.findBySheetIdOrderByListedDesc(sheetId));
   169	        Collections.reverse(listed);
   170	        listed.forEach(c -> byPerson.computeIfAbsent(c.getPersonId(), k -> new ArrayList<>()).add(c));
   171	        List<Claim> copies = new ArrayList<>();
   172	        Map<Claim, String> oldNumbers = new HashMap<>();
   173	        Map<Claim, LocalDate> openedOn = new HashMap<>();
   174	        Map<Claim, Long> originalIds = new HashMap<>();
   175	        for (Person person : theirs) {
   176	            for (Claim claim : byPerson.getOrDefault(person.getId(), List.of())) {
   177	                Claim copy = claim.cloned(toSheet, personIds.get(person.getId()));
   178	                copies.add(copy);
   179	                if (claim.getShownNumber() != null) {
   180	                    oldNumbers.put(copy, claim.getShownNumber());
   181	                }
   182	                openedOn.put(copy, openedOn(claim));
   183	                originalIds.put(copy, claim.getId());
   184	            }
   185	        }
   186	        claims.saveAllAndFlush(copies);
   187	        // a forward-only rate stays one: the copies of the claims added before it was saved keep leaving it out
   188	        long beforeCopies = copies.stream().mapToLong(Claim::getId).min().orElse(rates.maxClaimId() + 1) - 1;
   189	        forwardOnly.forEach((rate, after) -> rate.forwardAfter(copies.stream()
   190	                .filter(c -> originalIds.get(c) <= after).mapToLong(Claim::getId).max().orElse(beforeCopies)));
   191	        rates.flush();
   192	
   193	        Map<String, String> renumbered = new HashMap<>();
   194	        copies.stream().filter(oldNumbers::containsKey).sorted(Comparator.comparing(openedOn::get))
   195	                .forEach(claim -> {
   196	                    claimService.numberArrived(toSheet, claim);
   197	                    renumbered.put(oldNumbers.get(claim), claim.getShownNumber());
   198	                });
   199	        // a correction, or a claim split off another, names the claim it came from by its new number
   200	        for (Claim claim : copies) {
   201	            if (claim.getCorrects() != null) {
   202	                claim.setCorrects(renumbered.getOrDefault(claim.getCorrects(), claim.getCorrects()));
   203	            }
   204	            if (claim.getSplitFrom() != null) {
   205	                claim.setSplitFrom(renumbered.getOrDefault(claim.getSplitFrom(), claim.getSplitFrom()));
   206	            }
   207	        }
   208	        claims.flush();
   209	
   210	        events.publishEvent(new SheetCloned(sheetId, user, toSheet, null));
   211	        events.publishEvent(new SheetCloned(toSheet, user, null, sheetId));
   212	        // the copy had no figures before: everyone and the totals count as moved
   213	        rollup.changed(toSheet, user, new Rollup.Figures(Map.of(), null));
   214	        return sheet;
   215	    }
   216	
   217	    /** The sheet's today when the claim was opened: its first status after DRAFT; its date when it has no log of it. */
   218	    private static LocalDate openedOn(Claim claim) {
   219	        return claim.getLog().stream().filter(l -> l.getStatus() != ClaimStatus.DRAFT).map(ClaimLogLine::getOn)
   220	                .findFirst().orElse(claim.getDate());
   221	    }
   222	}
