82	    /** Add the person as above, their own terms from the date (null: from the beginning of time). */
83	    @Transactional
84	    public Person add(String sheetId, String user, String name, String grade, Integer terms, LocalDate termsFrom,
85	            String contact, String tagText) {
86	        String tagged = Tags.normalize(tagText);
87	        sheets.load(sheetId, user);
88	        sheetRows.lockById(sheetId);
89	        String trimmed = name.trim();
90	        if (inUse(sheetId, trimmed, null)) {
91	            throw nameInUse();
92	        }
93	        if (contact != null && people.existsBySheetIdAndContact(sheetId, contact)) {
94	            throw contactInUse();
95	        }
96	        Rollup.Figures before = rollup.figures(sheetId);
97	        Person added = new Person(sheetId, trimmed, grade);
98	        if (termsFrom != null) {
99	            if (terms != null) {
100	                added.termsFrom(terms, termsFrom);
101	            }
102	        } else {
103	            added.setTerms(terms);
104	        }
105	        added.setContact(contact);
106	        added.setTags(tagged);
107	        added.setPosition(people.maxPosition(sheetId) + 1);
108	        Person person = people.saveAndFlush(added);
109	        tags.use(sheetId, tagged);
110	        Integer termsNow = person.termsOn(sheets.today(sheetId));
111	        events.publishEvent(new PersonChanged("PERSON_ADDED", sheetId, user, trimmed, grade,
112	                termsNow == null ? null : termsNow.toString(), contact));
113	        rollup.changed(sheetId, user, before);
114	        return person;
115	    }
