137	    /**
138	     * Edit the person as above, their own terms recorded from a date: with a from-date, the terms (null: none)
139	     * are recorded from it, keeping those already recorded (one from the same date is replaced); with none, the
140	     * terms are those from the beginning of time, unless they are the terms in force on the sheet's today (as the
141	     * row showed them), which records nothing. When the terms recorded changed, the edit names the terms in force
142	     * on the sheet's today after it.
143	     */
144	    @Transactional
145	    public Person edit(String sheetId, String user, long personId, Long version, String name, String grade,
146	            LocalDate gradeFrom, Integer terms, LocalDate termsFrom, String contact, String tagText) {
147	        String tagged = tagText == null ? null : Tags.normalize(tagText);
148	        sheetRows.lockById(sheetId);
149	        Person person = people.findByIdAndSheetId(personId, sheetId)
150	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
151	        if (version != null && version != person.getVersion()) {
152	            throw edited();
153	        }
154	        String trimmed = name.trim();
155	        if (inUse(sheetId, trimmed, personId)
156	                || person.getAliases().stream().anyMatch(alias -> inUse(sheetId, alias, personId))) {
157	            throw nameInUse();
158	        }
159	        if (contact != null && people.existsBySheetIdAndContactAndIdNot(sheetId, contact, personId)) {
160	            throw contactInUse();
161	        }
162	        Rollup.Figures before = rollup.figures(sheetId);
163	        person.setName(trimmed);
164	        LocalDate today = sheets.today(sheetId);
165	        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
166	            person.gradeFrom(grade, gradeFrom != null ? gradeFrom : today);
167	        }
168	        boolean termsChanged;
169	        if (termsFrom != null) {
170	            termsChanged = person.termsFrom(terms, termsFrom);
171	        } else {
172	            termsChanged = !Objects.equals(terms, person.termsOn(today));
173	            if (termsChanged) {
174	                person.setTerms(terms);
175	            }
176	        }
177	        Integer termsNow = person.termsOn(today);
178	        String termsChange = !termsChanged ? null : termsNow == null ? "" : termsNow.toString();
179	        String contactChange = Objects.equals(contact, person.getContact()) ? null : contact == null ? "" : contact;
180	        person.setContact(contact);
181	        if (tagged != null) {
182	            person.setTags(tagged);
183	        }
184	        people.flush();
185	        if (tagged != null) {
186	            tags.use(sheetId, tagged);
187	        }
188	        events.publishEvent(new PersonChanged("PERSON_EDITED", sheetId, user, trimmed, person.gradeOn(today),
189	                termsChange, contactChange));
190	        rollup.changed(sheetId, user, before);
191	        return person;
192	    }
