194	    /**
195	     * Retire the person from a date; a date left out takes the sheet's today. Once the sheet's today reaches
196	     * it, their OPEN and PENDING claims not bound by a statement leave the live totals, so the figures it
197	     * moves are announced. The sheet stays locked
198	     * until the change commits, so a claim added meanwhile is checked against the new date.
199	     */
200	    @Transactional
201	    public Person retire(String sheetId, String user, long personId, LocalDate from) {
202	        sheetRows.lockById(sheetId);
203	        Person person = people.findByIdAndSheetId(personId, sheetId)
204	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
205	        LocalDate on = from != null ? from : sheets.today(sheetId);
206	        Rollup.Figures before = rollup.figures(sheetId);
207	        person.setRetiredFrom(on);
208	        people.flush();
209	        events.publishEvent(new PersonRetired(sheetId, user, person.getName(), on));
210	        rollup.changed(sheetId, user, before);
211	        return person;
212	    }
