214	    /**
215	     * Unretire a retired person on the sheet's today: they are no longer retired, their retirement kept as a past
216	     * one from its date to that today. Anyone not retired is refused. Their claims may come back into the live
217	     * totals, so the figures it moves are announced.
218	     */
219	    @Transactional
220	    public Person unretire(String sheetId, String user, long personId) {
221	        sheetRows.lockById(sheetId);
222	        Person person = people.findByIdAndSheetId(personId, sheetId)
223	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
224	        if (!person.isRetired()) {
225	            throw new ResponseStatusException(HttpStatus.CONFLICT, person.getName() + " is not retired");
226	        }
227	        LocalDate on = sheets.today(sheetId);
228	        Rollup.Figures before = rollup.figures(sheetId);
229	        person.unretire(on);
230	        people.flush();
231	        events.publishEvent(new PersonUnretired(sheetId, user, person.getName(), on));
232	        rollup.changed(sheetId, user, before);
233	        return person;
234	    }
