236	    /**
237	     * Move the person up or down the list: they swap places with the person above or below. The top person
238	     * cannot move up nor the bottom one down. Their versions stay as they are: a move edits neither of them.
239	     * Takes turns with other changes on the sheet.
240	     */
241	    @Transactional
242	    public Person move(String sheetId, String user, long personId, boolean up) {
243	        sheetRows.lockById(sheetId);
244	        List<Person> listed = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
245	        int at = -1;
246	        for (int i = 0; i < listed.size(); i++) {
247	            if (listed.get(i).getId() == personId) {
248	                at = i;
249	            }
250	        }
251	        if (at < 0) {
252	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person");
253	        }
254	        int to = up ? at - 1 : at + 1;
255	        if (to < 0 || to >= listed.size()) {
256	            throw new ResponseStatusException(HttpStatus.CONFLICT,
257	                    up ? "The top person cannot move up" : "The bottom person cannot move down");
258	        }
259	        Person person = listed.get(at);
260	        // the list is numbered afresh from 1 with the two swapped, so positions left by people who have
261	        // gone from the sheet close up
262	        for (int i = 0; i < listed.size(); i++) {
263	            int position = (i == at ? to : i == to ? at : i) + 1;
264	            if (listed.get(i).getPosition() != position) {
265	                people.setPosition(listed.get(i).getId(), position);
266	            }
267	        }
268	        events.publishEvent(new PersonMoved(sheetId, user, person.getName(), to + 1));
269	        return get(sheetId, personId);
270	    }
