280	        Person person = people.findByIdAndSheetId(personId, sheetId)
281	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
282	        LocalDate on = from != null ? from : sheets.today(sheetId);
283	        if (to != null && to.isBefore(on)) {
284	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
285	        }
286	        Rollup.Figures before = rollup.figures(sheetId);
287	        person.hold(on, to);
288	        people.flush();
289	        events.publishEvent(new PersonHeld(sheetId, user, person.getName(), on));
290	        rollup.changed(sheetId, user, before);
291	        return person;
292	    }
