308	        }
309	        LocalDate on = until != null ? until : sheets.today(sheetId);
310	        person.flag(trimmed, on);
311	        people.flush();
312	        events.publishEvent(new PersonFlagged(sheetId, user, person.getName(), trimmed, on));
