 60	    @Transactional
 61	    public Result importPeople(String sheetId, String user, String text) {
 62	        sheetRows.lockById(sheetId);
 63	        List<Planned> planned = new ArrayList<>();
 64	        Set<String> names = new HashSet<>();
 65	        Set<Long> updated = new HashSet<>();
 66	        Set<String> contacts = new HashSet<>();
 67	        String defaultGrade = sheets.settings(sheetId).defaultGrade();
 68	        for (String raw : text.split("\\R")) {
 69	            if (raw.isBlank()) continue;
 70	            Line line = parse(raw, defaultGrade);
 71	            Optional<Person> match = service.findByNameOrAlias(sheetId, line.name());
 72	            if (match.isEmpty() && service.inUse(sheetId, line.name(), null)) {
 73	                throw refused(raw, "the name \"" + line.name() + "\" is already in use");
 74	            }
 75	            if (!names.add(line.name().toLowerCase(Locale.ROOT))
 76	                    || match.isPresent() && !updated.add(match.get().getId())) {
 77	                throw refused(raw, "the name \"" + line.name() + "\" is given twice in the paste");
 78	            }
 79	            if (line.contact() != null) {
 80	                boolean taken = match.isPresent()
 81	                        ? people.existsBySheetIdAndContactAndIdNot(sheetId, line.contact(), match.get().getId())
 82	                        : people.existsBySheetIdAndContact(sheetId, line.contact());
 83	                if (taken) {
 84	                    throw refused(raw, "the contact \"" + line.contact() + "\" is already in use");
 85	                }
 86	                if (!contacts.add(line.contact())) {
 87	                    throw refused(raw, "the contact \"" + line.contact() + "\" is given twice in the paste");
 88	                }
 89	            }
 90	            planned.add(new Planned(line, match.orElse(null)));
 91	        }
 92	        if (planned.isEmpty()) {
 93	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Paste at least one line");
 94	        }
 95	        int added = 0;
 96	        for (Planned p : planned) {
 97	            Line line = p.line();
 98	            if (p.person() == null) {
 99	                service.add(sheetId, user, line.name(), line.grade(), line.terms(), line.contact());
100	                added++;
101	            } else {
102	                Person person = p.person();
103	                service.edit(sheetId, user, person.getId(), null, person.getName(), line.grade(), null,
104	                        line.terms() != null ? line.terms() : person.getTerms(),
105	                        line.contact() != null ? line.contact() : person.getContact());
106	            }
107	        }
108	        return new Result(added, planned.size() - added);
109	    }
