111	    private static Line parse(String raw, String defaultGrade) {
112	        String[] f = raw.split(",", -1);
113	        if (f.length < 2 || f.length > 4) throw refused(raw, "give a name, a grade, and optionally terms and a contact");
114	        String name = f[0].trim();
115	        if (name.isEmpty()) throw refused(raw, "give a name");
116	        if (name.length() > NAME_MAX) throw refused(raw, "the name is too long");
117	        String grade = f[1].isBlank() ? defaultGrade : f[1].trim();
118	        if (!GRADE.matcher(grade).matches()) throw refused(raw, "the grade must be A, B or C");
119	        Integer terms = null;
120	        if (f.length > 2 && !f[2].isBlank()) {
121	            String days = f[2].trim();
122	            if (!TERMS.matcher(days).matches()) throw refused(raw, "the terms must be a number of days");
123	            terms = Integer.valueOf(days);
124	        }
125	        String contact = null;
126	        if (f.length > 3 && !f[3].isBlank()) {
127	            if (f[3].length() > CONTACT_MAX) throw refused(raw, "the contact is too long");
128	            contact = f[3].trim().toLowerCase(Locale.ROOT);
129	        }
130	        return new Line(name, grade, terms, contact);
131	    }
