175	public class PersonMergeService {
176	
177	    private static final BigDecimal FULL_SHARE = new BigDecimal("100.00");
178	
179	    private final PersonRepository people;
180	    private final PatronRepository patrons;
181	    private final WatchRepository watches;
182	    private final ClaimRepository claims;
