207	    /** Merge the person into the other; answers with the other as they are now. */
208	    @Transactional
209	    public Person merge(String sheetId, String user, long personId, long intoId) {
210	        sheetRows.lockById(sheetId);
211	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
212	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can merge people");
213	        }
214	        if (personId == intoId) {
215	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be merged into themselves");
216	        }
217	        Person from = people.findByIdAndSheetId(personId, sheetId)
218	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
219	        Person into = people.findByIdAndSheetId(intoId, sheetId)
220	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "No such person"));
221	        if (from.isRetired() || into.isRetired()) {
222	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged");
223	        }
224	        Rollup.Figures before = rollup.figures(sheetId);
225	
226	        List<Claim> moving = new ArrayList<>(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId));
227	        moving.sort(Comparator.comparing(Claim::getId));
228	        for (Claim claim : moving) {
229	            claim.setPersonId(intoId);
230	        }
231	        claims.flush();
232	        for (Claim claim : moving) {
233	            claims.relist(claim.getId());
234	        }
235	
236	        into.addAlias(from.getName());
237	        from.getAliases().forEach(into::addAlias);
238	
239	        mergePatrons(sheetId, personId, intoId);
240	        mergePools(personId, intoId);
241	        crews.merge(personId, intoId);
242	        watches.deleteAll(watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId));
243	        statements.carry(sheetId, personId, sheetId, intoId);
244	        watches.flush();
245	        people.delete(from);
246	        people.flush();
247	
248	        events.publishEvent(new PersonMerged(sheetId, user, from.getName(), into.getName()));
249	        rollup.changed(sheetId, user, before);
250	        return into;
251	    }
252	
253	    /** The merged person's patrons join the other's, and whoever named the merged person names the other. */
254	    private void mergePatrons(String sheetId, long personId, long intoId) {
255	        List<Patron> theirs = patrons.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
256	        List<Patron> naming = patrons.findBySheetIdAndPatronIdOrderByIdAsc(sheetId, personId);
257	        Set<Long> intoPatrons = patrons.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, intoId).stream()
258	                .map(Patron::getPatronId).collect(Collectors.toCollection(LinkedHashSet::new));
259	        patrons.deleteAll(theirs);
260	        patrons.deleteAll(naming);
261	        patrons.flush();
262	        List<Patron> added = new ArrayList<>();
263	        for (Patron p : theirs) {
264	            long patronId = p.getPatronId();
265	            if (patronId != intoId && intoPatrons.add(patronId)) {
266	                added.add(new Patron(sheetId, intoId, patronId));
267	            }
268	        }
269	        for (Patron p : naming) {
270	            long namer = p.getPersonId();
271	            if (namer != intoId && !patrons.existsByPersonIdAndPatronId(namer, intoId)
272	                    && added.stream().noneMatch(a -> a.getPersonId() == namer)) {
273	                added.add(new Patron(sheetId, namer, intoId));
274	            }
275	        }
276	        patrons.saveAllAndFlush(added);
277	    }
278	
279	    /** The merged person's pool memberships move to the other, adding shares where the other is a member. */
280	    private void mergePools(long personId, long intoId) {
281	        Map<Long, PoolMember> intoByPool = poolMembers.findByPersonId(intoId).stream()
282	                .collect(Collectors.toMap(PoolMember::getPoolId, Function.identity()));
283	        for (PoolMember member : poolMembers.findByPersonId(personId)) {
284	            PoolMember existing = intoByPool.get(member.getPoolId());
285	            if (existing == null) {
286	                member.setPersonId(intoId);
287	            } else {
288	                existing.setShare(existing.getShare().add(member.getShare()).min(FULL_SHARE));
289	                poolMembers.delete(member);
290	            }
291	        }
292	        poolMembers.flush();
293	    }
294	}

