    75	    /** The sheet's figures now. */
    76	    public Figures figures(String sheetId) {
    77	        Sheet sheet = sheets.findById(sheetId).orElse(null);
    78	        LocalDate today = sheet == null ? LocalDate.now() : sheet.getToday();
    79	        RateTable table = new RateTable(rates.findBySheetId(sheetId), today,
    80	                new DatedSettings(settings.findBySheetId(sheetId)), sheet == null ? null : sheet.getPolicyDate(),
    81	                parents.of(sheetId));
    82	        Map<Long, List<Claim>> bySheet = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
    83	                .collect(Collectors.groupingBy(Claim::getPersonId));
    84	        Map<Long, PersonFigures> figures = new LinkedHashMap<>();
    85	        BigDecimal claimedTotal = BigDecimal.ZERO;
    86	        List<BigDecimal> dues = new ArrayList<>();
    87	        List<BigDecimal> overdues = new ArrayList<>();
    88	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
    89	            List<Claim> theirs = bySheet.getOrDefault(person.getId(), List.of());
    90	            BigDecimal claimed = Dues.claimed(theirs, person.leaves(), today);
    91	            BigDecimal due = Dues.total(person::gradeOn, theirs, table, person.leaves());
    92	            BigDecimal overdue = Dues.sum(person::gradeOn, Dues.overdue(theirs, person::gradeOn, table, person.leaves()), table);
    93	            claimedTotal = claimedTotal.add(claimed);
    94	            overdues.add(overdue.setScale(2, RoundingMode.HALF_UP));
    95	            if (due != null) {
    96	                dues.add(due.setScale(2, RoundingMode.HALF_UP));
    97	            }
    98	            figures.put(person.getId(), new PersonFigures(person.getName(), money(claimed),
    99	                    due == null ? "n/a" : money(due), money(overdue)));
   100	        }
   101	        return new Figures(figures, new Totals(money(claimedTotal), money(trimmedSum(dues)), money(trimmedSum(overdues))));
   102	    }
   103	
   104	    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
   105	    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
   106	        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
   107	        if (figures.size() < 3) {
   108	            return sum;
   109	        }
   110	        return sum.subtract(figures.stream().max(BigDecimal::compareTo).orElseThrow())
   111	                .subtract(figures.stream().min(BigDecimal::compareTo).orElseThrow());
   112	    }
   113	
   114	    /**
   115	     * Announce the figures the change moved since {@code before}: each person whose figures changed (one
   116	     * who did not exist before counting as changed), then the totals when they changed, then each person whose
   117	     * due-total went from at or below the alert threshold (or none) to above it. Nothing when no figure moved.
   118	     */
   119	    public void changed(String sheetId, String user, Figures before) {
   120	        Figures after = figures(sheetId);
   121	        List<PersonFigures> moved = new ArrayList<>();
   122	        after.people().forEach((id, now) -> {
   123	            if (!now.sameFigures(before.people().get(id))) {
   124	                moved.add(now);
   125	            }
   126	        });
   127	        Totals totals = Objects.equals(before.totals(), after.totals()) ? null : after.totals();
   128	        BigDecimal threshold = new DatedSettings(settings.findBySheetId(sheetId)).alertThreshold();
   129	        List<PersonFigures> alerts = new ArrayList<>();
   130	        if (threshold != null) {
   131	            after.people().forEach((id, now) -> {
   132	                PersonFigures was = before.people().get(id);
   133	                if (above(now, threshold) && (was == null || !above(was, threshold))) {
   134	                    alerts.add(now);
   135	                }
   136	            });
   137	        }
   138	        if (!moved.isEmpty() || totals != null) {
   139	            events.publishEvent(new RollupChanged(sheetId, user, moved, totals, alerts));
   140	        }
   141	    }
   142	
   143	    /** Whether the person's due-total is above the threshold; never when they have none. */
   144	    private static boolean above(PersonFigures figures, BigDecimal threshold) {
   145	        return !"n/a".equals(figures.dueTotal()) && new BigDecimal(figures.dueTotal()).compareTo(threshold) > 0;
   146	    }
   147	
   148	    private static String money(BigDecimal amount) {
   149	        return amount.setScale(2, RoundingMode.HALF_UP).toPlainString();
   150	    }
   151	}
