 81	    public record Then(String period, List<Shown> pools) {
 82	
 83	        /** The member's cut in the pool then; null when the pool or the member was not there, or had none. */
 84	        public BigDecimal cut(String pool, Member member) {
 85	            return pools.stream().filter(p -> p.name().equals(pool)).flatMap(p -> p.members().stream())
 86	                    .filter(m -> Objects.equals(m.personId(), member.personId())
 87	                            && Objects.equals(m.pool(), member.pool()))
 88	                    .map(Member::cut).filter(Objects::nonNull).findFirst().orElse(null);
 89	        }
