126	    /**
127	     * The pools on the sheet, sorted by name or else in the order they were added, each with its members and figures.
128	     */
129	    @Transactional(readOnly = true)
130	    public List<Shown> list(String sheetId, boolean asAdded) {
131	        List<Pool> all = asAdded ? pools.findBySheetIdOrderByIdAsc(sheetId) : pools.findBySheetIdOrderByNameAsc(sheetId);
132	        Map<Long, Pool> poolById = all.stream().collect(Collectors.toMap(Pool::getId, Function.identity()));
133	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
134	                .collect(Collectors.toMap(Person::getId, Function.identity()));
135	        Map<Long, List<PoolMember>> byPool = members.findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList())
136	                .stream().collect(Collectors.groupingBy(PoolMember::getPoolId));
137	        Map<Long, Long> above = new HashMap<>();
138	        byPool.values().forEach(ms -> ms.stream().filter(m -> m.getMemberPoolId() != null)
139	                .forEach(m -> above.put(m.getMemberPoolId(), m.getPoolId())));
140	        BigDecimal pot = sheets.settings(sheetId).pot();
141	        LocalDate today = sheets.today(sheetId);
142	        Set<Long> held = byId.values().stream().filter(p -> p.heldOn(today)).map(Person::getId)
143	                .collect(Collectors.toSet());
144	        Map<Long, Shown> shown = new HashMap<>();
145	        for (Pool pool : all) {
146	            show(pool.getId(), poolById, byId, byPool, above, pot, held, today, shown, new HashSet<>());
147	        }
148	        List<Shown> crewPools = crewPools(sheetId, byId, pot, held);
149	        Stream<Shown> listed = Stream.concat(all.stream().map(p -> shown.get(p.getId())), crewPools.stream());
150	        return asAdded ? listed.toList() : listed.sorted(Comparator.comparing(Shown::name)).toList();
151	    }
