153	    /**
154	     * The pools as they stood at the end of each period whose to-date is on or before the sheet's today, in the
155	     * order of the periods. Not in a transaction of its own: each period is read in its own rolled-back one.
156	     */
157	    public List<Then> history(String sheetId) {
158	        LocalDate today = sheets.today(sheetId);
159	        List<Period> ended = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
160	                .filter(p -> !p.getToDate().isAfter(today)).toList();
161	        List<Then> result = new ArrayList<>();
162	        for (Period period : ended) {
163	            if (period.getToDate().equals(today)) {
164	                result.add(new Then(period.getName(), list(sheetId)));
165	                continue;
166	            }
167	            List<Shown> then = pasts.asOf(sheetId, period.getToDate(), () -> {
168	                // the store now holds the sheet as it was: drop anything read before it was put there
169	                entities.clear();
170	                List<Shown> read = list(sheetId);
171	                entities.clear();
172	                return read;
173	            });
174	            result.add(new Then(period.getName(), then));
175	        }
176	        return result;
177	    }
