179	    /** The sheet's crews, in the order they were added, each as a pool of its lead and members at equal shares. */
180	    private List<Shown> crewPools(String sheetId, Map<Long, Person> byId, BigDecimal pot, Set<Long> held) {
181	        List<Crew> all = crews.findBySheetIdOrderByNameAsc(sheetId).stream()
182	                .sorted(Comparator.comparing(Crew::getId)).toList();
183	        Map<Long, List<CrewMember>> byCrew = crewMembers.findByCrewIdInOrderByIdAsc(all.stream().map(Crew::getId)
184	                .toList()).stream().collect(Collectors.groupingBy(CrewMember::getCrewId));
185	        List<Shown> result = new ArrayList<>();
186	        for (Crew crew : all) {
187	            List<Person> who = Stream.concat(Stream.of(crew.getLeadId()),
188	                    byCrew.getOrDefault(crew.getId(), List.of()).stream().map(CrewMember::getPersonId))
189	                    .map(byId::get).filter(Objects::nonNull).toList();
190	            List<Member> listed = new ArrayList<>();
191	            if (!who.isEmpty()) {
192	                BigDecimal each = HUNDRED.divide(BigDecimal.valueOf(who.size()), 2, RoundingMode.HALF_EVEN);
193	                BigDecimal first = HUNDRED.subtract(each.multiply(BigDecimal.valueOf(who.size() - 1))).setScale(2);
194	                for (int i = 0; i < who.size(); i++) {
195	                    Person p = who.get(i);
196	                    listed.add(new Member(p.getId(), null, p.getName(), i == 0 ? first : each, p.isRetired(), null));
197	                }
198	            }
199	            BigDecimal total = listed.stream().map(Member::share).reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
200	            boolean balanced = total.compareTo(HUNDRED) == 0;
201	            boolean allRetired = listed.stream().allMatch(Member::retired);
202	            List<Member> withCuts = balanced && pot != null && !allRetired ? cut(listed, pot, held) : listed;
203	            result.add(new Shown(crew.getName(), withCuts, total, balanced, true));
204	        }
205	        return result;
206	    }
