208	    /** The pool shown with its figures, the pool above it shown first since its cut there is this pool's pot. */
209	    private Shown show(long poolId, Map<Long, Pool> poolById, Map<Long, Person> byId,
210	            Map<Long, List<PoolMember>> byPool, Map<Long, Long> above, BigDecimal sheetPot, Set<Long> held,
211	            LocalDate today, Map<Long, Shown> shown, Set<Long> visiting) {
212	        Shown done = shown.get(poolId);
213	        if (done != null) {
214	            return done;
215	        }
216	        Pool pool = poolById.get(poolId);
217	        BigDecimal pot = sheetPot;
218	        Long parent = above.get(poolId);
219	        if (parent != null) {
220	            pot = null;
221	            if (poolById.containsKey(parent) && visiting.add(poolId)) {
222	                Shown up = show(parent, poolById, byId, byPool, above, sheetPot, held, today, shown, visiting);
223	                pot = up.members().stream().filter(m -> pool.getName().equals(m.pool())).map(Member::cut)
224	                        .filter(Objects::nonNull).findFirst().orElse(null);
225	            }
226	        }
227	        List<Member> listed = new ArrayList<>();
228	        List<Boolean> current = new ArrayList<>();
229	        for (PoolMember m : byPool.getOrDefault(poolId, List.of())) {
230	            int before = listed.size();
231	            if (m.getMemberPoolId() != null) {
232	                Pool member = poolById.get(m.getMemberPoolId());
233	                if (member != null) {
234	                    listed.add(new Member(null, member.getName(), member.getName(), m.getShare().setScale(2), false,
235	                            null));
236	                }
237	            } else if (byId.containsKey(m.getPersonId())) {
238	                Person p = byId.get(m.getPersonId());
239	                listed.add(new Member(p.getId(), null, p.getName(), m.getShare().setScale(2), p.isRetired(), null));
240	            }
241	            if (listed.size() > before) {
242	                current.add(m.coversOn(today));
243	            }
244	        }
245	        BigDecimal total = BigDecimal.ZERO;
246	        List<Member> counted = new ArrayList<>();
247	        for (int i = 0; i < listed.size(); i++) {
248	            if (current.get(i)) {
249	                counted.add(listed.get(i));
250	                total = total.add(listed.get(i).share());
251	            }
252	        }
253	        total = total.setScale(2);
254	        boolean balanced = total.compareTo(HUNDRED) == 0;
255	        List<Member> withCuts = listed;
256	        boolean allRetired = !counted.isEmpty() && counted.stream().allMatch(Member::retired);
257	        if (balanced && pot != null && !allRetired) {
258	            // members out of their dates keep no cut; the others are cut as if they were all the pool's members
259	            List<Member> cut = cut(counted, pot, held);
260	            withCuts = new ArrayList<>();
261	            for (int i = 0, c = 0; i < listed.size(); i++) {
262	                withCuts.add(current.get(i) ? cut.get(c++) : listed.get(i));
263	            }
264	        }
265	        Shown result = new Shown(pool.getName(), withCuts, total, balanced, false);
266	        shown.put(poolId, result);
267	        return result;
268	    }
