270	    /**
271	     * The members, in the order added, each with their cut of the pot spread over the members with a cut (not retired
272	     * nor held); the remainder goes to the smallest non-zero cut among them, the latest added on a tie.
273	     */
274	    private static List<Member> cut(List<Member> shown, BigDecimal pot, Set<Long> held) {
275	        List<Boolean> cutting = shown.stream()
276	                .map(m -> !m.retired() && (m.personId() == null || !held.contains(m.personId()))).toList();
277	        BigDecimal shares = BigDecimal.ZERO;
278	        for (int i = 0; i < shown.size(); i++) {
279	            if (cutting.get(i)) {
280	                shares = shares.add(shown.get(i).share());
281	            }
282	        }
283	        List<BigDecimal> cuts = new ArrayList<>();
284	        for (int i = 0; i < shown.size(); i++) {
285	            Member m = shown.get(i);
286	            cuts.add(!cutting.get(i) ? BigDecimal.ZERO.setScale(2)
287	                    : pot.multiply(m.share()).divide(shares, 2, RoundingMode.HALF_EVEN));
288	        }
289	        int smallest = -1;
290	        int last = -1;
291	        for (int i = 0; i < shown.size(); i++) {
292	            if (!cutting.get(i)) {
293	                continue;
294	            }
295	            if (last < 0 || shown.get(i).share().signum() != 0) {
296	                last = i;
297	            }
298	            if (cuts.get(i).signum() != 0
299	                    && (smallest < 0 || cuts.get(i).compareTo(cuts.get(smallest)) <= 0)) {
300	                smallest = i;
301	            }
302	        }
303	        int receiver = smallest >= 0 ? smallest : last;
304	        if (receiver >= 0) {
305	            BigDecimal sum = cuts.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
306	            cuts.set(receiver, cuts.get(receiver).add(pot.subtract(sum)).setScale(2));
307	        }
308	        List<Member> cut = new ArrayList<>();
309	        for (int i = 0; i < shown.size(); i++) {
310	            Member m = shown.get(i);
311	            cut.add(new Member(m.personId(), m.pool(), m.name(), m.share(), m.retired(), cuts.get(i)));
312	        }
313	        return cut;
314	    }
