358	    /**
359	     * Add another pool of the sheet to the named pool with a share like a person's; refused when the member is the
360	     * pool itself or contains it through any chain, is a member of a pool already, or the chain would be more than
361	     * three pools deep.
362	     */
363	    @Transactional
364	    public void addPoolMember(String sheetId, String user, String poolName, String memberName, String text,
365	            LocalDate from, LocalDate to) {
366	        BigDecimal share = share(text);
367	        dates(from, to);
368	        sheetRows.lockById(sheetId);
369	        Pool pool = pool(sheetId, poolName);
370	        Pool member = pools.findBySheetIdAndName(sheetId, memberName == null ? "" : memberName.strip())
371	                .orElseThrow(() -> new PoolRefused("Choose a pool on this sheet."));
372	        List<Pool> all = pools.findBySheetIdOrderByNameAsc(sheetId);
373	        Map<Long, Long> above = new HashMap<>();
374	        Map<Long, List<Long>> below = new HashMap<>();
375	        members.findByPoolIdInOrderByIdAsc(all.stream().map(Pool::getId).toList()).stream()
376	                .filter(m -> m.getMemberPoolId() != null).forEach(m -> {
377	                    above.put(m.getMemberPoolId(), m.getPoolId());
378	                    below.computeIfAbsent(m.getPoolId(), k -> new ArrayList<>()).add(m.getMemberPoolId());
379	                });
380	        int levelsAbove = 1;
381	        boolean contains = member.getId().equals(pool.getId());
382	        Set<Long> seen = new HashSet<>(List.of(pool.getId()));
383	        for (Long up = above.get(pool.getId()); up != null && seen.add(up); up = above.get(up)) {
384	            levelsAbove++;
385	            contains |= up.equals(member.getId());
386	        }
387	        if (contains) {
388	            throw new PoolRefused("A pool cannot contain itself.");
389	        }
390	        if (above.containsKey(member.getId())) {
391	            throw new PoolRefused(member.getName() + " is a member of a pool already.");
392	        }
393	        if (levelsAbove + depth(member.getId(), below, new HashSet<>()) > DEPTH_MAX) {
394	            throw new PoolRefused("A chain of pools is at most " + DEPTH_MAX + " deep.");
395	        }
396	        members.saveAndFlush(PoolMember.ofPool(pool.getId(), member.getId(), share).dated(from, to));
397	        events.publishEvent(new PoolMemberAdded(sheetId, user, pool.getName(), member.getName(), share, from, to));
398	    }
399	
400	    /** How many pools deep the chain is from this pool down: 1 when no pool is a member of it. */
401	    private static int depth(long poolId, Map<Long, List<Long>> below, Set<Long> seen) {
402	        if (!seen.add(poolId)) {
403	            return 0;
404	        }
405	        int deepest = 0;
406	        for (long child : below.getOrDefault(poolId, List.of())) {
407	            deepest = Math.max(deepest, depth(child, below, seen));
408	        }
409	        return 1 + deepest;
410	    }
411	
412	    private Pool pool(String sheetId, String poolName) {
413	        return pools.findBySheetIdAndName(sheetId, poolName == null ? "" : poolName.strip())
414	                .orElseThrow(() -> new PoolRefused("No such pool on this sheet."));
415	    }
