417	    /** Refused when both dates are given and the to-date is before the from-date. */
418	    private static void dates(LocalDate from, LocalDate to) {
419	        if (from != null && to != null && to.isBefore(from)) {
420	            throw new PoolRefused("The to-date cannot be before the from-date.");
421	        }
422	    }
423	
424	    private static BigDecimal share(String text) {
425	        String s = text == null ? "" : text.strip();
426	        if (!s.matches("\\d{1,3}(\\.\\d{1,2})?")) {
427	            throw new PoolRefused("Enter a share with up to two decimals.");
428	        }
429	        BigDecimal share = new BigDecimal(s).setScale(2);
430	        if (share.signum() <= 0 || share.compareTo(HUNDRED) > 0) {
431	            throw new PoolRefused("A share is more than 0.00 and at most 100.00.");
432	        }
433	        return share;
434	    }
