   152	        List<Claim> leaving = new ArrayList<>(claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId));
   153	        Collections.reverse(leaving);
   154	        List<Claim> arriving = new ArrayList<>();
   155	        Map<Claim, String> oldNumbers = new HashMap<>();
   156	        Map<Claim, LocalDate> openedOn = new HashMap<>();
   157	        Map<Claim, Long> addedAs = new HashMap<>();
   158	        for (Claim claim : leaving) {
   159	            Claim copy = claim.arriving(toSheet, arrived.getId());
   160	            if (claim.isStated()) {
   161	                copy.bind(claim.getStatedDue(), claim.isStatedAsShown());
