   181	        for (Claim claim : arriving) {
   182	            if (claim.getCorrects() != null) {
   183	                claim.setCorrects(renumbered.getOrDefault(claim.getCorrects(), claim.getCorrects()));
   184	            }
   185	            if (claim.getSplitFrom() != null) {
   186	                claim.setSplitFrom(renumbered.getOrDefault(claim.getSplitFrom(), claim.getSplitFrom()));
   187	            }
   188	        }
