   202	        events.publishEvent(new PersonTransferred(sheetId, user, person.getName(), toSheet, null));
   203	        rollup.changed(sheetId, user, beforeHere);
   204	        events.publishEvent(new PersonTransferred(toSheet, user, person.getName(), null, sheetId));
   205	        if (into != null) {
   206	            events.publishEvent(new PersonMerged(toSheet, user, person.getName(), into.getName()));
   207	        }
   208	        rollup.changed(toSheet, user, beforeThere);
