   211	    /**
   212	     * Undo the transfer that brought the person to this sheet: only a steward of this sheet may, on the sheet's
   213	     * today they arrived; the person is then transferred back to the sheet they came from, as a transfer does.
   214	     */
   215	    @Transactional
   216	    public void undo(String sheetId, String user, long personId) {
   217	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
   218	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can undo a transfer");
   219	        }
   220	        Person person = people.findByIdAndSheetId(personId, sheetId)
   221	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
   222	        String origin = person.getOrigin();
   223	        if (origin == null || person.getArrivedOn() == null || !person.getArrivedOn().equals(sheets.today(sheetId))) {
   224	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a transfer that arrived today can be undone");
   225	        }
   226	        String name = person.getName();
   227	        Rollup.Figures before = rollup.figures(sheetId);
   228	        transfer(sheetId, user, personId, origin);
   229	        events.publishEvent(new PersonTransferUndone(sheetId, user, name, origin));
   230	        rollup.changed(sheetId, user, before);
   231	    }
   232	
   233	    /** The sheet's today when the claim was opened: its first status after DRAFT; its date when it has no log of it. */
   234	    private static LocalDate openedOn(Claim claim) {
   235	        return claim.getLog().stream().filter(l -> l.getStatus() != ClaimStatus.DRAFT).map(ClaimLogLine::getOn)
   236	                .findFirst().orElse(claim.getDate());
   237	    }
