131	/** Whether the claim is OPEN or PENDING, not bound by a statement, and its person's retirement date is reached
132	 * on the sheet's today: it then counts in no live total. */
133	export function retiredOut(c: Claim, retiredNow: boolean): boolean {
134	  return retiredNow && !c.stated && (c.status === 'OPEN' || c.status === 'PENDING');
