    20	/**
    21	 * The people's plans on a sheet. Generating makes, for every plan in the order they were added, a DRAFT claim of
    22	 * the plan's amount for each plan date (the start, then every N days; or that day of every month from the start's month, on the month's
    23	 * last day when it is shorter, leaving out dates before the start) up to its end and the sheet's today that has
    24	 * none yet, dated that day with an empty note, by every rule of the claim form. A date the form refuses is skipped,
    25	 * writing nothing, and tried again the next time. A viewer's generate makes nothing: every claim it would make is
    26	 * refused.
    27	 */
    28	@Service
    29	public class Plans {
    30	
    31	    private final PlanRepository plans;
    32	    private final PlanClaimRepository made;
    33	    private final PersonRepository people;
    34	    private final ClaimService claims;
    35	    private final SheetService sheets;
    36	    private final SheetRepository sheetRows;
    37	    private final ApplicationEventPublisher events;
    38	    private final TransactionTemplate transaction;
    39	    private final AccessService access;
