    41	    public Plans(PlanRepository plans, PlanClaimRepository made, PersonRepository people, ClaimService claims,
    42	            SheetService sheets, SheetRepository sheetRows, ApplicationEventPublisher events,
    43	            PlatformTransactionManager transactions, AccessService access) {
    44	        this.access = access;
    45	        this.plans = plans;
    46	        this.made = made;
    47	        this.people = people;
    48	        this.claims = claims;
    49	        this.sheets = sheets;
    50	        this.sheetRows = sheetRows;
    51	        this.events = events;
    52	        this.transaction = new TransactionTemplate(transactions);
    53	    }
    54	
    55	    /** The plans on the sheet in the order they were added. */
    56	    @Transactional(readOnly = true)
    57	    public List<Plan> list(String sheetId) {
    58	        return plans.findBySheetIdOrderByIdAsc(sheetId);
    59	    }
    60	
    61	    /** How many claims the plan has made so far. */
    62	    @Transactional(readOnly = true)
    63	    public long generated(Plan plan) {
    64	        return made.countByPlanId(plan.getId());
    65	    }
    66	
    67	    /**
    68	     * Add a plan to the person, running every N days or monthly on a day of the month (exactly one given); refused
    69	     * when its end is before its start, its interval is under one day or its day is not 1 to 31.
    70	     */
    71	    @Transactional
    72	    public void add(String sheetId, String user, long personId, BigDecimal amount, LocalDate start, Integer every,
    73	            Integer day, LocalDate end) {
    74	        if ((every == null) == (day == null)) {
    75	            throw new PlanRefused("Enter either every how many days or a day of the month.");
    76	        }
    77	        if (every != null && every < 1) {
    78	            throw new PlanRefused("Enter a whole number of days, at least 1.");
    79	        }
    80	        if (day != null && (day < 1 || day > 31)) {
    81	            throw new PlanRefused("Enter a day of the month from 1 to 31.");
    82	        }
    83	        if (end.isBefore(start)) {
    84	            throw new PlanRefused("The end cannot be before the start.");
    85	        }
    86	        sheets.load(sheetId, user);
    87	        sheetRows.lockById(sheetId);
    88	        Person person = people.findByIdAndSheetId(personId, sheetId)
    89	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
    90	        plans.saveAndFlush(new Plan(sheetId, personId, amount, start, every, day, end));
    91	        events.publishEvent(new PlanAdded(sheetId, user, person.getName(), amount, start, every, day, end));
    92	    }
    93	
    94	    /** Make the claims the plans are due up to the sheet's today; returns how many were made. */
    95	    public int generate(String sheetId, String user) {
    96	        sheets.load(sheetId, user);
    97	        if (access.isViewer(sheetId, user)) {
    98	            return 0;
    99	        }
   100	        LocalDate today = sheets.today(sheetId);
   101	        int count = 0;
   102	        for (Plan plan : list(sheetId)) {
   103	            LocalDate last = plan.getEnd().isBefore(today) ? plan.getEnd() : today;
   104	            for (LocalDate on : plan.datesUpTo(last)) {
   105	                if (makeClaim(sheetId, user, plan, on)) {
   106	                    count++;
   107	                }
   108	            }
   109	        }
   110	        return count;
   111	    }
   112	
   113	    /** Make the plan's claim on the date, each in its own change: false when it has one or the form refuses it. */
   114	    private boolean makeClaim(String sheetId, String user, Plan plan, LocalDate on) {
   115	        try {
   116	            return Boolean.TRUE.equals(transaction.execute(status -> {
   117	                sheetRows.lockById(sheetId);
   118	                if (made.existsByPlanIdAndOn(plan.getId(), on)) {
   119	                    return false;
   120	                }
   121	                claims.add(sheetId, user, plan.getPersonId(), plan.getAmount(), on, "");
