69	    /**
70	     * Add a period from {@code from} to {@code to}, both inclusive. Refused when the name is taken on the
71	     * sheet, the to-date is before the from-date, or it shares a date with another period. Two users adding
72	     * one at the same moment wait on each other, so no two overlap. A cap, when given, is the most OPEN or PENDING
73	     * claims a person may have in it, and must be a whole number of at least 1.
74	     */
75	    @Transactional
76	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
77	        sheets.load(sheetId, user);
78	        sheetRows.lockById(sheetId);
79	        if (to.isBefore(from)) {
80	            throw new PeriodRefused("The to-date is before the from-date.");
81	        }
82	        if (cap != null && cap < 1) {
83	            throw new PeriodRefused("The cap must be a whole number of at least 1.");
84	        }
85	        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
86	            throw new PeriodRefused("That period name is already in use on this sheet.");
87	        }
88	        if (list(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
89	            throw new PeriodRefused("The period overlaps another period.");
90	        }
91	        Period period = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
92	        events.publishEvent(new PeriodAdded(sheetId, user, name, from, to, cap));
93	        return period;
94	    }
95	
96	    /**
97	     * Generate one period per calendar month from the from-date's month to the to-date's month, each running
98	     * from the first to the last day of its month and named yyyy-mm. A month whose name is already a period on
99	     * the sheet, or whose days overlap one, is left out; the others are still made. Refused when the to-date is
100	     * before the from-date. Returns the periods made, earliest first.
101	     */
102	    @Transactional
103	    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
104	        sheets.load(sheetId, user);
105	        sheetRows.lockById(sheetId);
106	        if (to.isBefore(from)) {
107	            throw new PeriodRefused("The to-date is before the from-date.");
108	        }
109	        List<Period> existing = new ArrayList<>(list(sheetId));
110	        List<Period> made = new ArrayList<>();
111	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
112	            addUnlessTaken(sheetId, user, month.toString(), month.atDay(1), month.atEndOfMonth(), existing, made);
113	        }
114	        return made;
115	    }
116	
117	    /**
118	     * Generate the four calendar quarters of the given year, named yyyy-Q1 to yyyy-Q4, each running from the first
119	     * day of its first month to the last day of its third. A quarter whose name is already a period on the sheet,
120	     * or whose days overlap one, is left out; the others are still made. Returns the periods made, earliest first.
121	     */
122	    @Transactional
123	    public List<Period> generateQuarters(String sheetId, String user, int year) {
124	        sheets.load(sheetId, user);
125	        sheetRows.lockById(sheetId);
126	        List<Period> existing = new ArrayList<>(list(sheetId));
127	        List<Period> made = new ArrayList<>();
128	        for (int quarter = 1; quarter <= 4; quarter++) {
129	            YearMonth start = YearMonth.of(year, quarter * 3 - 2);
130	            addUnlessTaken(sheetId, user, String.format("%04d-Q%d", year, quarter), start.atDay(1),
131	                    start.plusMonths(2).atEndOfMonth(), existing, made);
132	        }
133	        return made;
134	    }
