221	    /**
222	     * When the sheet's today is changed and it has grace days, close every open period (neither closed nor
223	     * soft-closed) whose to-date plus the grace days is before the new today, in order of their to-dates, each as a close by hand would.
224	     */
225	    @EventListener
226	    @Transactional
227	    public void on(TodayChanged e) {
228	        Integer grace = sheets.graceDays(e.sheetId());
229	        if (grace == null) {
230	            return;
231	        }
232	        sheetRows.lockById(e.sheetId());
233	        list(e.sheetId()).stream()
234	                .filter(p -> !p.isFixed() && p.getToDate().plusDays(grace).isBefore(e.today()))
235	                .sorted(Comparator.comparing(Period::getToDate))
236	                .forEach(p -> fix(e.sheetId(), e.user(), p, true, false));
237	    }
238	
239	    /**
240	     * Each person's carried figure for the period, for every person on the sheet: the due figures as they stand of
241	     * their claims that count on the sheet's today (neither left out by a retirement nor deferred, see
242	     * {@link Dues#counts}) due by a date inside a period ending before it starts and still OPEN or PENDING at the end
243	     * of its last day, by the status log, added up per person, with the opening balances pasted for them in it.
244	     */
245	    private Map<Long, BigDecimal> carried(String sheetId, Period period, Map<Long, Person> byId, RateTable table) {
246	        List<Period> all = list(sheetId);
247	        Map<Long, BigDecimal> carried = new HashMap<>();
248	        byId.keySet().forEach(id -> carried.put(id, BigDecimal.ZERO.setScale(2)));
249	        claims.findBySheetIdOrderByIdDesc(sheetId).stream()
250	                .filter(c -> byId.containsKey(c.getPersonId()))
251	                .filter(c -> all.stream().anyMatch(home -> home.contains(c.getDueBy())
252	                        && home.getToDate().isBefore(period.getFromDate())))
253	                .filter(c -> c.getDeferredUntil() == null || !table.today().isBefore(c.getDeferredUntil()))
254	                .filter(c -> Dues.countsAsOf(c, byId.get(c.getPersonId()).leaves(), table.today(), period.getToDate()))
255	                .filter(c -> {
256	                    ClaimStatus then = Dues.statusAsOf(c, period.getToDate());
257	                    return then == ClaimStatus.OPEN || then == ClaimStatus.PENDING;
258	                })
259	                .forEach(c -> {
260	                    BigDecimal due = Dues.figure(c, byId.get(c.getPersonId())::gradeOn, table);
261	                    if (due != null) {
262	                        carried.merge(c.getPersonId(), due, BigDecimal::add);
263	                    }
264	                });
265	        period.getPersonOpenings().forEach((id, amount) -> {
266	            if (byId.containsKey(id)) {
267	                carried.merge(id, amount, BigDecimal::add);
268	            }
269	        });
270	        carried.replaceAll((id, t) -> t.setScale(2, RoundingMode.HALF_UP));
271	        return carried;
272	    }
273	
274	    /** Fix the period's due-totals and carried figures as of the end of its last day and close it, or soft-close it. */
275	    private void fix(String sheetId, String user, Period period, boolean auto, boolean soft) {
276	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
277	                .collect(Collectors.toMap(Person::getId, p -> p));
278	        RateTable table = rates.table(sheetId);
279	        Map<Long, BigDecimal> totals = new HashMap<>();
280	        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
281	        claims.findBySheetIdOrderByIdDesc(sheetId).stream()
282	                .filter(c -> period.contains(c.getDueBy())
283	                        && Dues.countsAsOf(c, byId.get(c.getPersonId()).leaves(), table.today(), period.getToDate()))
284	                .forEach(c -> {
285	                    BigDecimal due = Dues.figure(c, byId.get(c.getPersonId())::gradeOn, table);
286	                    if (due != null) {
287	                        totals.merge(c.getPersonId(), due, BigDecimal::add);
288	                    }
289	                });
290	        totals.replaceAll((id, t) -> t.setScale(2, RoundingMode.HALF_UP));
291	        period.close(totals, carried(sheetId, period, byId, table), soft);
292	        BigDecimal total = period.getClosedTotal().setScale(2, RoundingMode.HALF_UP);
293	        periods.flush();
294	        events.publishEvent(new PeriodClosed(sheetId, user, period.getName(), total, auto, soft));
295	    }
