344	    /** The closed period whose dates contain the date, if any. */
345	    @Transactional(readOnly = true)
346	    public Optional<Period> closedOn(String sheetId, LocalDate date) {
347	        return list(sheetId).stream().filter(p -> p.isClosed() && p.contains(date)).findFirst();
348	    }
349	
350	    /** The soft-closed period whose dates contain the date, if any. */
351	    @Transactional(readOnly = true)
352	    public Optional<Period> softClosedOn(String sheetId, LocalDate date) {
353	        return list(sheetId).stream().filter(p -> p.isSoftClosed() && p.contains(date)).findFirst();
354	    }
355	
356	    /**
357	     * Refuse a change to a claim due by any of the dates when a closed period contains it. Holds the
358	     * sheet's lock until the transaction ends, so a period cannot close while the change is made.
359	     */
360	    @Transactional
361	    public void requireOpen(String sheetId, LocalDate... dates) {
362	        sheetRows.lockById(sheetId);
363	        for (LocalDate date : dates) {
364	            closedOn(sheetId, date).ifPresent(p -> {
365	                throw new ClosedPeriodRefused(p.getName());
366	            });
367	        }
368	    }
