219	    private static final Pattern AMOUNT = Pattern.compile("\\d{1,12}(\\.\\d{1,2})?");
220	
221	    private record Line(Person person, Period period, BigDecimal amount) {
222	    }
223	
224	    private final PeriodRepository periods;
225	    private final PersonRepository people;
226	    private final SheetService sheets;
227	    private final SheetRepository sheetRows;
228	    private final ApplicationEventPublisher events;
229	
230	    public OpeningImportService(PeriodRepository periods, PersonRepository people, SheetService sheets,
231	            SheetRepository sheetRows, ApplicationEventPublisher events) {
232	        this.periods = periods;
233	        this.people = people;
234	        this.sheets = sheets;
235	        this.sheetRows = sheetRows;
236	        this.events = events;
237	    }
238	
239	    /** Add an opening balance per line, in order; returns how many lines went through. */
240	    @Transactional
241	    public int importOpenings(String sheetId, String user, String text) {
242	        sheets.load(sheetId, user);
243	        sheetRows.lockById(sheetId);
244	        List<Period> all = periods.findBySheetIdOrderByFromDateAsc(sheetId);
245	        List<Line> lines = new ArrayList<>();
246	        for (String raw : text.split("\\R")) {
247	            if (raw.isBlank()) continue;
248	            lines.add(parse(sheetId, all, raw));
249	        }
250	        if (lines.isEmpty()) {
251	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Paste at least one line");
252	        }
253	        for (Line line : lines) {
254	            line.period().addOpening(line.person().getId(), line.amount());
255	            events.publishEvent(new OpeningSet(sheetId, user, line.person().getName(), line.period().getName(),
256	                    line.amount()));
257	        }
258	        periods.flush();
259	        return lines.size();
260	    }
261	
262	    private Line parse(String sheetId, List<Period> all, String raw) {
263	        String[] f = raw.split(",", -1);
264	        if (f.length != 3) throw refused(raw, "give a name, a period and an amount");
265	        String name = f[0].trim();
266	        Person person = name.isEmpty() ? null
267	                : people.findBySheetIdAndNameOrAlias(sheetId, name).stream().findFirst().orElse(null);
268	        if (person == null) throw refused(raw, "no one named \"" + name + "\" is on the sheet");
269	        String periodName = f[1].trim();
270	        Period period = all.stream().filter(p -> p.getName().equalsIgnoreCase(periodName)).findFirst()
271	                .orElseThrow(() -> refused(raw, "no period named \"" + periodName + "\" is on the sheet"));
272	        String amount = f[2].trim();
273	        if (!AMOUNT.matcher(amount).matches()) {
274	            throw refused(raw, "the amount must be 0.00 or more, with up to two decimals");
275	        }
276	        return new Line(person, period, new BigDecimal(amount));
277	    }
278	
279	    private static ResponseStatusException refused(String line, String why) {
280	        return new ResponseStatusException(HttpStatus.CONFLICT, "Line \"" + line + "\": " + why);
281	    }
282	}
