   125	    /** The sheet then; a grade with no rate in force then takes its parent sheets' rates as they are now. */
   126	    private SheetThen then(String sheetId, LocalDate date, State state) {
   127	        DatedSettings settingsThen = new DatedSettings(state.settings().stream()
   128	                .map(s -> new SheetSetting(sheetId, s.key(), s.from(), s.value())).toList());
   129	        RateTable table = new RateTable(
   130	                state.rates().stream().map(r -> new Rate(sheetId, r.grade(), r.from(), r.to(), r.pct())
   131	                        .forwardAfter(r.forwardAfter())).toList(),
   132	                date, settingsThen, state.policyDate(), parents.from(sheetId, settingsThen.parent()));
   133	        Map<Long, Person> byId = new LinkedHashMap<>();
   134	        for (PersonRow row : state.people()) {
   135	            byId.put(row.id(), person(sheetId, row));
   136	        }
   137	        Map<Long, Map<Long, Claim>> claimsByPerson = new LinkedHashMap<>();
   138	        for (ClaimRow row : state.claims()) {
   139	            claimsByPerson.computeIfAbsent(row.personId(), k -> new LinkedHashMap<>()).put(row.id(), claim(sheetId, row));
   140	        }
   141	        return new SheetThen(table, byId, claimsByPerson);
   142	    }
