   144	    private static Person person(String sheetId, PersonRow row) {
   145	        GradeRow first = row.grades().stream().filter(g -> g.from() == null).findFirst()
   146	                .orElse(row.grades().isEmpty() ? new GradeRow(null, null) : row.grades().get(0));
   147	        Person person = new Person(sheetId, row.name(), first.grade());
   148	        row.grades().stream().filter(g -> g != first).forEach(g -> person.gradeFrom(g.grade(), g.from()));
   149	        row.holds().forEach(h -> person.hold(h.from(), h.to()));
   150	        person.setRetiredFrom(row.retiredFrom());
   151	        return person;
   152	    }
