   155	        Claim claim = new Claim(sheetId, row.personId(), row.amount(), row.date(), "", null).restoredAs(row.id());
   156	        claim.setStatus(row.status());
   157	        claim.setCorrectsDate(row.correctsDate());
   158	        claim.setDueBy(row.dueBy());
   159	        claim.setDeferredUntil(row.deferredUntil());
   160	        claim.setSettledDue(row.settledDue());
   161	        claim.setHeld(Boolean.TRUE.equals(row.held()));
   162	        if (row.stated()) {
   163	            claim.bind(row.statedDue(), Boolean.TRUE.equals(row.statedAsShown()));
   164	        }
   165	        return claim;
   166	    }
