    87	    @Transactional
    88	    public void take(String sheetId, String user, long personId, LocalDate asOf) {
    89	        Person person = people.findByIdAndSheetId(personId, sheetId)
    90	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
    91	        RateTable table = rates.table(sheetId);
    92	        LocalDate on = asOf == null ? table.today() : asOf;
    93	        if (on.isAfter(table.today())) {
    94	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A statement cannot be taken as of a date after today");
    95	        }
    96	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
    97	        Person then;
    98	        Map<Long, Claim> claimsThen;
    99	        if (on.isBefore(table.today())) {
   100	            DayEnds.SheetThen sheetThen = dayEnds.asOf(sheetId, on)
   101	                    .filter(t -> t.people().containsKey(personId))
   102	                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT,
   103	                            "The person was not on the sheet by that date"));
   104	            then = sheetThen.people().get(personId);
   105	            claimsThen = sheetThen.claimsOf(personId);
   106	            table = sheetThen.table();
   107	        } else {
