   109	            claimsThen = new LinkedHashMap<>();
   110	            theirs.forEach(c -> claimsThen.put(c.getId(), c));
   111	        }
   112	        Rollup.Figures before = rollup.figures(sheetId);
   113	        BigDecimal dueTotal = Dues.total(then::gradeOn, List.copyOf(claimsThen.values()), table, then.leaves());
   114	        int counting = 0;
   115	        for (Claim claim : theirs) {
   116	            Claim stood = claimsThen.get(claim.getId());
   117	            if (stood != null && Dues.counts(stood, then.leaves(), table.today())) {
   118	                claim.bind(Dues.figure(stood, then::gradeOn, table));
   119	                counting++;
