   131	     * Carry a person's statements to the person receiving them in a merge or transfer: the receiver's count
   132	     * becomes their own plus the other's, and the receiver's last statement stays theirs (or, having none,
   133	     * becomes the other's). The other's statements are dropped from them.
   134	     */
   135	    @Transactional
   136	    public void carry(String fromSheet, long fromPerson, String toSheet, long toPerson) {
   137	        List<Statement> theirs = statements.findBySheetIdAndPersonIdOrderByIdAsc(fromSheet, fromPerson);
   138	        List<Statement> own = statements.findBySheetIdAndPersonIdOrderByIdAsc(toSheet, toPerson);
   139	        // taken in order by id: the other's come first, then the receiver's own taken again after them
   140	        List<Statement> carried = new ArrayList<>();
   141	        theirs.forEach(s -> carried.add(s.carried(toSheet, toPerson)));
   142	        own.forEach(s -> carried.add(s.carried(toSheet, toPerson)));
   143	        statements.deleteAll(theirs);
   144	        statements.deleteAll(own);
   145	        statements.flush();
   146	        statements.saveAllAndFlush(carried);
   147	    }
