   149	    /** Cancel the person's last statement; only a steward may, and only while the person has one. */
   150	    @Transactional
   151	    public void cancel(String sheetId, String user, long personId) {
   152	        Person person = people.findByIdAndSheetId(personId, sheetId)
   153	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
   154	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
   155	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can cancel a statement");
   156	        }
   157	        List<Statement> taken = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, personId);
   158	        if (taken.isEmpty()) {
   159	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person has no statement to cancel");
   160	        }
   161	        Rollup.Figures before = rollup.figures(sheetId);
   162	        Statement last = taken.get(taken.size() - 1);
   163	        for (Claim claim : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
   164	            if (claim.isStated()) {
