    19	/**
    20	 * The as-of view of a sheet: a request on a sheet carrying an as-of date ({@code X-As-Of}, the date the
    21	 * user's screen shows the sheet as of) reads the sheet as it stood at the end of that date (see
    22	 * {@link SheetPasts}); every change it asks for is refused (409, writing nothing). Loading a sheet goes
    23	 * through. A request without the date is the live sheet.
    24	 */
    25	@Component
    26	public class AsOfFilter extends OncePerRequestFilter {
    27	
    28	    static final String HEADER = "X-As-Of";
    29	
    30	    private static final String PREFIX = "/api/sheets/";
    31	
    32	    private static final String REFUSAL = "{\"message\":\"The sheet is shown as of a date: nothing on it can change.\"}";
    33	
    34	    private final SheetPasts pasts;
    35	
    36	    public AsOfFilter(SheetPasts pasts) {
    37	        this.pasts = pasts;
    38	    }
    39	
    40	    @Override
    41	    protected boolean shouldNotFilter(HttpServletRequest request) {
    42	        String asOf = request.getHeader(HEADER);
    43	        return asOf == null || asOf.isBlank() || !path(request).startsWith(PREFIX);
    44	    }
    45	
    46	    @Override
    47	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
    48	            throws ServletException, IOException {
    49	        String path = path(request);
    50	        String rest = path.substring(PREFIX.length());
    51	        int slash = rest.indexOf('/');
    52	        String sheet = UriUtils.decode(slash < 0 ? rest : rest.substring(0, slash), StandardCharsets.UTF_8).trim();
    53	        LocalDate date;
    54	        try {
    55	            date = LocalDate.parse(request.getHeader(HEADER).trim());
    56	        } catch (DateTimeParseException e) {
    57	            response.sendError(HttpStatus.BAD_REQUEST.value());
    58	            return;
    59	        }
    60	        boolean reading = HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod());
    61	        if (!reading) {
    62	            if (path.endsWith("/load")) {
    63	                chain.doFilter(request, response);
    64	                return;
    65	            }
    66	            response.setStatus(HttpStatus.CONFLICT.value());
    67	            response.setContentType(MediaType.APPLICATION_JSON_VALUE);
    68	            response.getWriter().write(REFUSAL);
    69	            return;
    70	        }
    71	        try {
    72	            pasts.asOf(sheet, date, () -> {
    73	                try {
    74	                    chain.doFilter(request, response);
    75	                } catch (IOException e) {
    76	                    throw new UncheckedIOException(e);
    77	                } catch (ServletException e) {
    78	                    throw new IllegalStateException(e);
    79	                }
    80	                return null;
    81	            });
    82	        } catch (UncheckedIOException e) {
    83	            throw e.getCause();
    84	        }
    85	    }
    86	
    87	    private static String path(HttpServletRequest request) {
    88	        return request.getRequestURI().substring(request.getContextPath().length());
    89	    }
    90	}
