   117	     * the read does is kept. A sheet never started is read as it is.
   118	     */
   119	    public <T> T asOf(String sheetId, LocalDate date, Supplier<T> read) {
   120	        ReentrantLock lock = shown.computeIfAbsent(sheetId, k -> new ReentrantLock());
   121	        lock.lock();
   122	        try {
   123	            return rolledBack.execute(status -> {
   124	                status.setRollbackOnly();
   125	                put(sheetId, date);
   126	                return read.get();
   127	            });
   128	        } finally {
   129	            lock.unlock();
   130	        }
   131	    }
   132	
   133	    private void put(String sheetId, LocalDate date) {
   134	        // take the sheet's lock first, as every change does, so a change under way is waited for, not deadlocked on
   135	        List<LocalDate> today = jdbc.queryForList("SELECT today FROM sheet WHERE id = ? FOR UPDATE", LocalDate.class,
   136	                sheetId);
   137	        if (today.isEmpty()) {
   138	            return;
   139	        }
   140	        if (date.isBefore(today.get(0))) {
   141	            Optional<Rows> then = pasts.findFirstBySheetIdAndEndedOnLessThanEqualOrderByIdDesc(sheetId, date)
   142	                    .map(p -> json.readValue(p.getState(), new TypeReference<Rows>() {
   143	                    }));
   144	            for (int i = TABLES.size() - 1; i >= 0; i--) {
   145	                Scope scope = TABLES.get(i);
   146	                jdbc.update("DELETE FROM " + scope.table() + " WHERE " + scope.where(), sheetId);
   147	            }
   148	            if (then.isPresent()) {
   149	                putSheet(sheetId, then.get().sheet());
   150	                for (Scope scope : TABLES) {
   151	                    then.get().tables().getOrDefault(scope.table(), List.of()).forEach(row -> insert(scope.table(), row));
   152	                }
   153	            } else {
   154	                startSheet(sheetId);
   155	            }
   156	        }
   157	        jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", date, sheetId);
   158	    }
   159	
   160	    /** The sheet's own row as it was. */
   161	    private void putSheet(String sheetId, Map<String, String> row) {
   162	        List<String> names = columns("SHEET").stream().map(Column::name)
   163	                .filter(c -> !SHEET_KEPT.contains(c) && row.containsKey(c)).toList();
   164	        if (names.isEmpty()) {
   165	            return;
   166	        }
   167	        List<Object> values = new ArrayList<>();
   168	        names.forEach(c -> values.add(row.get(c)));
   169	        values.add(sheetId);
   170	        jdbc.update("UPDATE sheet SET " + names.stream().map(c -> c + " = ?").collect(Collectors.joining(", "))
   171	                + " WHERE id = ?", values.toArray());
   172	    }
   173	
   174	    /** The sheet's own row as it was when it was started: every column at its default. */
   175	    private void startSheet(String sheetId) {
   176	        List<String> sets = columns("SHEET").stream().filter(c -> !SHEET_KEPT.contains(c.name()))
   177	                .filter(c -> c.defaulted() || c.nullable())
   178	                .map(c -> c.name() + (c.defaulted() ? " = DEFAULT" : " = NULL")).toList();
   179	        if (!sets.isEmpty()) {
   180	            jdbc.update("UPDATE sheet SET " + String.join(", ", sets) + " WHERE id = ?", sheetId);
   181	        }
   182	    }
   183	
   184	    private void insert(String table, Map<String, String> row) {
   185	        List<String> names = columns(table).stream().map(Column::name).filter(row::containsKey).toList();
   186	        jdbc.update("INSERT INTO " + table + " (" + String.join(", ", names) + ") VALUES ("
   187	                + names.stream().map(c -> "?").collect(Collectors.joining(", ")) + ")",
   188	                names.stream().map(row::get).toArray());
   189	    }
   190	
   191	    private List<Map<String, String>> select(String table, String where, String sheetId) {
   192	        List<String> names = columns(table).stream().map(Column::name).toList();
   193	        return jdbc.query("SELECT " + String.join(", ", names) + " FROM " + table + " WHERE " + where,
   194	                (rs, n) -> {
   195	                    Map<String, String> row = new LinkedHashMap<>();
   196	                    for (int i = 0; i < names.size(); i++) {
   197	                        row.put(names.get(i), rs.getString(i + 1));
   198	                    }
   199	                    return row;
   200	                }, sheetId);
   201	    }
   202	
   203	    /** The table's columns that are written (not computed from the others), in order. */
   204	    private List<Column> columns(String table) {
   205	        return columns.computeIfAbsent(table, t -> jdbc.query(
   206	                "SELECT column_name, is_nullable, column_default FROM information_schema.columns"
   207	                        + " WHERE table_schema = 'PUBLIC' AND table_name = ? AND is_generated = 'NEVER'"
   208	                        + " ORDER BY ordinal_position",
   209	                (rs, n) -> new Column(rs.getString(1), "YES".equals(rs.getString(2)), rs.getString(3) != null), t));
   210	    }
   211	}
