    18	/**
    19	 * The holidays on a sheet, earliest first; no date is on it twice. A claim's due-by, when it is fixed as the
    20	 * claim is added, is the terms-th business day after its date, skipping weekends and the holidays on the sheet
    21	 * then (see {@link #dueBy}). A holiday added later fixes again the due-by of every claim on the sheet that is
    22	 * not SETTLED or VOID and is due on or after it, from the claim's date with the terms it was fixed with.
    23	 */
    24	@Service
    25	public class HolidayService {
    26	
    27	    private final HolidayRepository holidays;
    28	    private final SheetService sheets;
    29	    private final SheetRepository sheetRows;
    30	    private final ClaimRepository claims;
    31	    private final Rollup rollup;
    32	    private final ApplicationEventPublisher events;
    33	
    34	    public HolidayService(HolidayRepository holidays, SheetService sheets, SheetRepository sheetRows,
    35	            ClaimRepository claims, Rollup rollup, ApplicationEventPublisher events) {
    36	        this.holidays = holidays;
    37	        this.sheets = sheets;
    38	        this.sheetRows = sheetRows;
    39	        this.claims = claims;
    40	        this.rollup = rollup;
    41	        this.events = events;
    42	    }
    43	
    44	    @Transactional(readOnly = true)
    45	    public List<Holiday> list(String sheetId) {
    46	        return holidays.findBySheetIdOrderByDayAsc(sheetId);
    47	    }
    48	
    49	    /**
    50	     * Add a holiday, fixing again the due-by of each claim not SETTLED or VOID due on or after it; refused when
    51	     * the date is already on the sheet's list.
    52	     */
    53	    @Transactional
    54	    public Holiday add(String sheetId, String user, LocalDate date) {
    55	        sheets.load(sheetId, user);
    56	        sheetRows.lockById(sheetId);
    57	        if (holidays.existsBySheetIdAndDay(sheetId, date)) {
    58	            throw new HolidayRefused("That date is already a holiday on this sheet.");
    59	        }
    60	        Rollup.Figures before = rollup.figures(sheetId);
    61	        Holiday saved = holidays.saveAndFlush(new Holiday(sheetId, date));
    62	        Set<LocalDate> days = list(sheetId).stream().map(Holiday::getDay).collect(Collectors.toSet());
    63	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
    64	            if (claim.getStatus() != ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.VOID
    65	                    && !claim.getDueBy().isBefore(date)) {
    66	                claim.setDueBy(businessDaysAfter(claim.getDate(), claim.getTerms(), days));
    67	            }
    68	        }
    69	        claims.flush();
    70	        events.publishEvent(new HolidayAdded(sheetId, user, date));
    71	        rollup.changed(sheetId, user, before);
    72	        return saved;
    73	    }
    74	
    75	    /** The due-by of a claim dated {@code date} with these terms, see {@link #businessDaysAfter}. */
    76	    @Transactional(readOnly = true)
    77	    public LocalDate dueBy(String sheetId, LocalDate date, int terms) {
    78	        Set<LocalDate> days = list(sheetId).stream().map(Holiday::getDay).collect(Collectors.toSet());
    79	        return businessDaysAfter(date, terms, days);
    80	    }
    81	
    82	    /**
    83	     * The {@code terms}-th business day after the date, counting forward from the day after it and skipping
    84	     * every Saturday, Sunday and holiday given; the date itself when the terms are 0 or less.
    85	     */
    86	    public static LocalDate businessDaysAfter(LocalDate date, int terms, Set<LocalDate> holidays) {
    87	        LocalDate day = date;
    88	        for (int left = terms; left > 0; ) {
    89	            day = day.plusDays(1);
    90	            if (businessDay(day, holidays)) {
    91	                left--;
    92	            }
    93	        }
    94	        return day;
    95	    }
    96	
    97	    private static boolean businessDay(LocalDate day, Set<LocalDate> holidays) {
    98	        DayOfWeek dow = day.getDayOfWeek();
    99	        return dow != DayOfWeek.SATURDAY && dow != DayOfWeek.SUNDAY && !holidays.contains(day);
   100	    }
   101	}

