     6	/**
     7	 * An action the sheet's permission matrix governs, with the roles that may take it when the matrix leaves
     8	 * it blank (the standing rule): open, settle, void and close by clerk and steward; reassign and reopen by
     9	 * steward. Its setting key is perm-&lt;action&gt;, its value a comma separated list of roles.
    10	 */
    11	public enum Permission {
    12	    OPEN(EnumSet.of(Role.CLERK, Role.STEWARD)),
    13	    SETTLE(EnumSet.of(Role.CLERK, Role.STEWARD)),
    14	    VOID(EnumSet.of(Role.CLERK, Role.STEWARD)),
    15	    REASSIGN(EnumSet.of(Role.STEWARD)),
    16	    CLOSE(EnumSet.of(Role.CLERK, Role.STEWARD)),
    17	    REOPEN(EnumSet.of(Role.STEWARD));
    18	
    19	    /** A permission value as written: blank, or roles separated by commas. */
    20	    public static final String ROLES = "(\\s*(clerk|steward)\\s*(,\\s*(clerk|steward)\\s*)*)?";
    21	
    22	    private final Set<Role> standing;
    23	
    24	    Permission(Set<Role> standing) {
    25	        this.standing = standing;
    26	    }
    27	
    28	    /** The action as it is written: lower case. */
    29	    public String action() {
    30	        return name().toLowerCase();
    31	    }
    32	
    33	    /** The setting key: perm-&lt;action&gt;. */
    34	    public String key() {
    35	        return "perm-" + action();
    36	    }
    37	
    38	    /** Whether the role may take the action under the value set (null or blank: the standing rule). */
    39	    public boolean allows(String value, Role role) {
    40	        if (value == null || value.isBlank()) {
    41	            return standing.contains(role);
    42	        }
    43	        for (String r : value.split(",")) {
    44	            if (r.trim().equals(role.key())) {
    45	                return true;
    46	            }
    47	        }
    48	        return false;
    49	    }
    50	}
