    48	        if (!(sheet instanceof String id)) {
    49	            return true;
    50	        }
    51	        String refusal = access.isArchived(id.trim()) ? ARCHIVED
    52	                : access.isViewer(id.trim(), user.trim()) ? REFUSAL : null;
